    origin: 'ALL',
    harvestSeason: 'ALL',
    minimumOrderRange: { min: 0, max: 1000 },
    cuppingScoreRange: { min: 0, max: 100 },
    altitudeRange: { min: 0, max: 2000 },
    certifications: [],
    incoterms: 'ALL',
  });

  // Fetch products from API
