                        onClick={exportToCSV}
                        variant="outline"
                        size="sm"
                        className="border-amber-600 text-amber-600 hover:bg-amber-50"
                      >
                        <Download className="mr-2 h-4 w-4" />
                        Export CSV
                      </Button>
                      <Button
                        onClick={() => {
                          setSelectedProducts(new Set());
                          setShowBulkActions(false);
                        }}
                        variant="ghost"
                        size="sm"
                        className="text-amber-600 hover:bg-amber-50"
                      >
                        Clear Selection
                      </Button>
                    </div>
                  </div>
                </div>
              )}

              {/* Product Grid Header */}
              <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                <div className="flex items-center gap-4">
                  <h2 className="text-lg font-semibold text-forest-800">
                    {loading ? (
                      <span className="flex items-center gap-2">
                        <Loader2 className="h-4 w-4 animate-spin" />
                        Loading...
                      </span>
                    ) : (
                      <>
                        {pagination.total} Product
                        {pagination.total !== 1 ? 's' : ''} Found
                        {filteredProducts.length !== pagination.total && (
                          <span className="text-sm text-gray-500">
                            ({filteredProducts.length} shown)
                          </span>
                        )}
                      </>
                    )}
                  </h2>
                  {!loading && filteredProducts.length > 0 && (
                    <Button
                      onClick={handleSelectAll}
                      variant="outline"
                      size="sm"
                      className="border-forest-300 text-forest-600 hover:bg-forest-50"
                    >
                      {selectedProducts.size === filteredProducts.length
                        ? 'Deselect All'
                        : 'Select All'}
                    </Button>
                  )}
                </div>

                <div className="flex items-center gap-2">
                  <Button
                    onClick={exportToCSV}
                    variant="outline"
                    size="sm"
                    className="border-forest-300 text-forest-600 hover:bg-forest-50"
                    disabled={loading || filteredProducts.length === 0}
                  >
                    <FileText className="mr-2 h-4 w-4" />
                    Export Catalog
                  </Button>
                </div>
              </div>

              {loading ? (
                <div className="flex items-center justify-center py-12">
                  <Loader2 className="h-8 w-8 animate-spin text-forest-600" />
                  <span className="ml-2 text-forest-600">
                    Loading products...
                  </span>
                </div>
              ) : error ? (
                <div className="rounded-lg border border-red-200 bg-red-50 p-6 text-center">
                  <div className="text-red-600">
                    <Coffee className="mx-auto mb-2 h-8 w-8" />
                    <h3 className="mb-2 text-lg font-semibold">
                      Error Loading Products
                    </h3>
                    <p className="mb-4">{error}</p>
                    <Button
                      onClick={fetchProducts}
                      className="bg-red-600 text-white hover:bg-red-700"
                    >
                      Try Again
                    </Button>
                  </div>
                </div>
              ) : filteredProducts.length === 0 ? (
                <div className="rounded-lg border border-gray-200 bg-gray-50 p-12 text-center">
                  <Coffee className="mx-auto mb-4 h-12 w-12 text-gray-400" />
                  <h3 className="mb-2 text-lg font-semibold text-gray-600">
                    No Products Found
                  </h3>
                  <p className="text-gray-500">
                    Try adjusting your filters to see more products.
                  </p>
                </div>
              ) : (
                <>
                  <ProductGrid
                    products={filteredProducts}
                    locale="en"
                    viewMode={viewMode}
                    onViewModeChange={setViewMode}
                    selectedProducts={selectedProducts}
                    onProductSelect={handleProductSelect}
                    showSelection={true}
                  />

                  {/* Pagination Controls */}
                  {pagination.totalPages > 1 && (
                    <div className="mt-8 flex items-center justify-between">
                      <div className="text-sm text-gray-600">
                        Showing {(pagination.page - 1) * pagination.limit + 1}{' '}
                        to{' '}
                        {Math.min(
                          pagination.page * pagination.limit,
                          pagination.total
                        )}{' '}
                        of {pagination.total} products
                      </div>

                      <div className="flex items-center gap-2">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() =>
                            setPagination(prev => ({
                              ...prev,
                              page: prev.page - 1,
                            }))
                          }
                          disabled={pagination.page <= 1 || loading}
                        >
                          Previous
                        </Button>

                        <div className="flex items-center gap-1">
                          {Array.from(
                            { length: Math.min(5, pagination.totalPages) },
                            (_, i) => {
                              const pageNum = i + 1;
                              const isCurrentPage = pageNum === pagination.page;

                              return (
                                <Button
                                  key={pageNum}
                                  variant={
                                    isCurrentPage ? 'default' : 'outline'
                                  }
                                  size="sm"
                                  onClick={() =>
                                    setPagination(prev => ({
                                      ...prev,
                                      page: pageNum,
                                    }))
                                  }
                                  disabled={loading}
                                  className={
                                    isCurrentPage
                                      ? 'bg-forest-600 text-white'
                                      : ''
                                  }
                                >
                                  {pageNum}
                                </Button>
                              );
                            }
                          )}

                          {pagination.totalPages > 5 && (
                            <>
                              <span className="px-2 text-gray-400">...</span>
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={() =>
                                  setPagination(prev => ({
                                    ...prev,
                                    page: pagination.totalPages,
                                  }))
                                }
                                disabled={loading}
                              >
                                {pagination.totalPages}
                              </Button>
                            </>
                          )}
                        </div>

                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() =>
                            setPagination(prev => ({
                              ...prev,
                              page: prev.page + 1,
                            }))
                          }
                          disabled={
                            pagination.page >= pagination.totalPages || loading
                          }
                        >
                          Next
                        </Button>
                      </div>
                    </div>
                  )}
                </>
              )}
            </div>
          </div>
        </ContentContainer>
      </ContentSection>

      {/* CTA Section */}
      <ContentSection className="bg-gradient-to-r from-forest-600 to-forest-700 py-16 text-white">
        <ContentContainer className="text-center">
          <SectionHeading size="xl" className="mb-4 text-white">
            Can&apos;t Find What You&apos;re Looking For?
          </SectionHeading>
          <p className="mx-auto mb-8 max-w-2xl text-lg text-forest-50">
            Our team can source custom coffee products to meet your specific
            requirements. Contact us for personalized sourcing solutions.
          </p>
          <div className="flex flex-col justify-center gap-4 sm:flex-row">
            <ServerButton
              size="lg"
              className="bg-amber-600 text-white hover:bg-amber-700"
            >
              <Search className="mr-2 h-5 w-5" />
              Custom Sourcing
            </ServerButton>
            <ServerButton
              size="lg"
              variant="outline"
              className="border-white text-white hover:bg-white hover:text-forest-600"
            >
              <ShoppingCart className="mr-2 h-5 w-5" />
              Contact Sales Team
            </ServerButton>
          </div>
        </ContentContainer>
      </ContentSection>
    </div>
  );
}

