  screenSize: '',
  moistureMax: null,
  defectRateMax: null,
  certifications: [],
  origin: '',
  quantity: null,
  unit: 'MT',
  tolerance: null,
  isRecurringOrder: false,
  recurringFrequency: '',
  incoterms: '',
  destinationPort: '',
  destinationCountry: '',
  preferredDeliveryDate: '',
  packaging: '',
  preferredCurrency: 'USD',
  paymentMethod: '',
  paymentTerms: '',
  companyName: '',
  contactPerson: '',
  position: '',
  email: '',
  phone: '',
  website: '',
  street: '',
  city: '',
  state: '',
  postalCode: '',
  country: '',
  businessType: '',
  companySize: '',
  additionalRequirements: '',
  sampleRequired: false,
  sampleAddress: '',
  urgencyReason: '',
};

const steps = [
  { id: 1, title: 'Product Requirements', icon: Coffee },
  { id: 2, title: 'Quantity & Delivery', icon: Package },
  { id: 3, title: 'Payment Terms', icon: CreditCard },
  { id: 4, title: 'Company Information', icon: Building2 },
  { id: 5, title: 'Additional Details', icon: FileText },
];

export default function QuotePage({
  params,
}: {
  params: Promise<{ locale: Locale }>;
}) {
  const { locale } = use(params);
  // Use the multi-step form hook
  const {
    currentStep,
    formData,
    progress,
    updateFormData,
    nextStep,
    prevStep,
  } = useMultiStepForm<RFQFormData>(initialFormData, steps.length);

  // Convert 0-based step to 1-based for display
  const displayStep = currentStep + 1;

  // Use the RFQ form hook for submission
  const {
    loading: isSubmitting,
    success: isSubmitted,
    error: submitError,
    rfqNumber,
    submitRfq,
    clearError,
  } = useRfqForm();

  // Use hydration-safe RFQ number as fallback
  const fallbackRfqNumber = useHydrationSafeRfqNumber();

  const handleSubmit = async () => {
    try {
      // Map form data to RFQ request format
      const rfqRequest = {
        // Product Requirements
        productType: [formData.coffeeType],
        grade: [formData.grade],
        origin: [formData.origin],
        processingMethod: [formData.processingMethod],
        certifications: formData.certifications,

        // Quantity & Delivery
        quantity: formData.quantity || 0,
        quantityUnit: formData.unit,
        deliveryTerms: formData.incoterms,
        targetPrice: 0, // Will be filled by sales team
        currency: formData.preferredCurrency,
        deliveryDate: formData.preferredDeliveryDate
          ? new Date(formData.preferredDeliveryDate)
          : new Date(), // Use current date without Date.now() to avoid hydration issues
        deliveryLocation: `${formData.destinationPort}, ${formData.destinationCountry}`,

        // Recurring Order
        isRecurringOrder: formData.isRecurringOrder,
        recurringFrequency: formData.isRecurringOrder
          ? (formData.recurringFrequency as any)
          : undefined,

        // Payment Terms
        paymentTerms: formData.paymentTerms,
        paymentMethod: [formData.paymentMethod],

        // Company Information
        companyName: formData.companyName,
        contactPerson: formData.contactPerson,
        email: formData.email,
        phone: formData.phone,
        country: formData.country,
        businessType: formData.businessType,

        // Additional Details
        additionalRequirements: formData.additionalRequirements,
        sampleRequired: formData.sampleRequired,
        urgency: formData.urgencyReason
          ? 'high'
          : ('medium' as 'low' | 'medium' | 'high'),

        // Metadata
        locale: locale,
      };

      await submitRfq(rfqRequest);
    } catch (error) {
      // Handle error silently or with proper error state management
      // In production, this would be logged to an error tracking service
      // The error state is already managed by the useRfqForm hook
    }
  };

  if (isSubmitted) {
    return (
      <div className="min-h-screen bg-forest-50 py-16">
        <div className="container mx-auto max-w-2xl px-4">
          <Card className="text-center shadow-forest">
            <CardContent className="pb-16 pt-16">
              <CheckCircle className="mx-auto mb-6 h-16 w-16 text-forest-600" />
              <h1 className="mb-4 text-3xl font-bold text-gray-900">
                Quote Request Submitted Successfully!
              </h1>
              <p className="mb-6 text-lg text-gray-600">
                Thank you for your interest in our premium Vietnamese coffee.
                Our team will review your requirements and respond within 24
                hours.
              </p>
              <div className="mb-6 rounded-lg border border-forest-200 bg-forest-50 p-4">
                <p className="text-sm text-forest-600">Reference Number</p>
                <p className="font-mono text-xl font-bold text-forest-800">
                  {rfqNumber || fallbackRfqNumber}
                </p>
              </div>
              <Button
                className="bg-forest-600 shadow-forest hover:bg-forest-700"
                onClick={() => (window.location.href = `/${locale}/products`)}
              >
                Browse Our Products
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-forest-50 py-16">
      <div className="container mx-auto max-w-4xl px-4">
        {/* Header */}
        <div className="mb-12 text-center">
          <h1 className="mb-4 text-4xl font-bold text-gray-900">
            Request a Quote
          </h1>
          <p className="mx-auto max-w-2xl text-xl text-gray-600">
            Get competitive pricing for your coffee requirements. Our team will
            provide a detailed quotation based on your specifications.
          </p>
        </div>

        {/* Progress Bar */}
        <div className="mb-8">
          <div className="mb-4 flex items-center justify-between">
            {steps.map(step => {
              const Icon = step.icon;
              const isActive = displayStep === step.id;
              const isCompleted = displayStep > step.id;

              return (
                <div key={step.id} className="flex flex-col items-center">
                  <div
                    className={`
                    mb-2 flex h-12 w-12 items-center justify-center rounded-full
                    ${
                      isCompleted
                        ? 'bg-forest-600 text-white'
                        : isActive
                          ? 'bg-emerald-500 text-white'
                          : 'bg-gray-200 text-gray-500'
                    }
                  `}
                  >
                    {isCompleted ? (
                      <CheckCircle className="h-6 w-6" />
                    ) : (
                      <Icon className="h-6 w-6" />
                    )}
                  </div>
                  <span
                    className={`text-sm font-medium ${isActive ? 'text-emerald-600' : 'text-gray-500'}`}
                  >
                    {step.title}
                  </span>
                </div>
              );
            })}
          </div>
          <Progress value={progress} className="h-2" />
        </div>

        {/* Form Content */}
        <Card className="shadow-forest">
          <CardHeader className="border-b border-forest-100">
            <CardTitle className="flex items-center text-forest-800">
              {displayStep === 1 && (
                <Coffee className="mr-2 h-5 w-5 text-forest-600" />
              )}
              {displayStep === 2 && (
                <Package className="mr-2 h-5 w-5 text-forest-600" />
              )}
              {displayStep === 3 && (
                <CreditCard className="mr-2 h-5 w-5 text-forest-600" />
              )}
              {displayStep === 4 && (
                <Building2 className="mr-2 h-5 w-5 text-forest-600" />
              )}
              {displayStep === 5 && (
                <FileText className="mr-2 h-5 w-5 text-forest-600" />
              )}
              {displayStep === 1 && 'Product Requirements'}
              {displayStep === 2 && 'Quantity & Delivery'}
              {displayStep === 3 && 'Payment Terms'}
              {displayStep === 4 && 'Company Information'}
              {displayStep === 5 && 'Additional Details'}
            </CardTitle>
            <CardDescription className="text-forest-600">
              Step {currentStep} of {steps.length}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            {/* Step 1: Product Requirements */}
            {displayStep === 1 && (
              <div className="space-y-6">
                <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                  <div>
                    <Label htmlFor="coffeeType">Coffee Type *</Label>
                    <Select
                      value={formData.coffeeType}
                      onValueChange={value =>
                        updateFormData({ coffeeType: value })
                      }
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select coffee type" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="ROBUSTA">Robusta</SelectItem>
                        <SelectItem value="ARABICA">Arabica</SelectItem>
                        <SelectItem value="BLEND">Blend</SelectItem>
