                      placeholder="e.g., 12.5"
                    />
                  </div>

                  <div>
                    <Label htmlFor="defectRateMax">
                      Maximum Defect Rate (%)
                    </Label>
                    <Input
                      type="number"
                      step="0.1"
                      max="100"
                      value={formData.defectRateMax || ''}
                      onChange={e =>
                        updateFormData({
                          defectRateMax: e.target.value
                            ? parseFloat(e.target.value)
                            : null,
                        })
                      }
                      placeholder="e.g., 5.0"
                    />
                  </div>
                </div>

                <div>
                  <Label>Required Certifications</Label>
                  <div className="mt-2 grid grid-cols-2 gap-4 md:grid-cols-3">
                    {[
                      'ORGANIC',
                      'FAIR_TRADE',
                      'RAINFOREST_ALLIANCE',
                      'UTZ',
                      '4C',
                      'KOSHER',
                    ].map(cert => (
                      <div key={cert} className="flex items-center space-x-2">
                        <Checkbox
                          id={cert}
                          checked={formData.certifications.includes(cert)}
                          onCheckedChange={checked => {
                            if (checked) {
                              updateFormData({
                                certifications: [
                                  ...formData.certifications,
                                  cert,
                                ],
                              });
                            } else {
                              updateFormData({
                                certifications: formData.certifications.filter(
                                  c => c !== cert
                                ),
                              });
                            }
                          }}
                        />
                        <Label htmlFor={cert} className="text-sm">
                          {cert.replace('_', ' ')}
                        </Label>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Step 2: Quantity & Delivery */}
            {displayStep === 2 && (
              <div className="space-y-6">
                <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
                  <div className="md:col-span-2">
                    <Label htmlFor="quantity">Quantity *</Label>
                    <Input
                      type="number"
                      value={formData.quantity || ''}
                      onChange={e =>
                        updateFormData({
                          quantity: e.target.value
                            ? parseFloat(e.target.value)
                            : null,
                        })
                      }
                      placeholder="Enter quantity"
                    />
                  </div>

                  <div>
                    <Label htmlFor="unit">Unit</Label>
                    <Select
                      value={formData.unit}
                      onValueChange={value => updateFormData({ unit: value })}
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="MT">Metric Tons (MT)</SelectItem>
                        <SelectItem value="KG">Kilograms (KG)</SelectItem>
                        <SelectItem value="LB">Pounds (LB)</SelectItem>
                        <SelectItem value="BAGS">Bags (60kg)</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                <div className="flex items-center space-x-2">
                  <Checkbox
                    id="isRecurringOrder"
                    checked={formData.isRecurringOrder}
                    onCheckedChange={checked =>
                      updateFormData({ isRecurringOrder: checked === true })
                    }
                  />
                  <Label htmlFor="isRecurringOrder">
                    This is a recurring order
                  </Label>
                </div>

                {formData.isRecurringOrder && (
                  <div>
                    <Label htmlFor="recurringFrequency">
                      Recurring Frequency
                    </Label>
                    <Select
                      value={formData.recurringFrequency}
                      onValueChange={value =>
                        updateFormData({ recurringFrequency: value })
                      }
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select frequency" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="MONTHLY">Monthly</SelectItem>
                        <SelectItem value="QUARTERLY">Quarterly</SelectItem>
                        <SelectItem value="SEMI_ANNUAL">Semi-Annual</SelectItem>
                        <SelectItem value="ANNUAL">Annual</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                )}

                <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                  <div>
                    <Label htmlFor="incoterms">Incoterms *</Label>
                    <Select
                      value={formData.incoterms}
                      onValueChange={value =>
                        updateFormData({ incoterms: value })
                      }
                    >
                      <SelectTrigger>
