import fs from 'fs/promises';
import path from 'path';

import matter from 'gray-matter';

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';

// Search schema
const SearchSchema = z.object({
  query: z.string().min(1),
  type: z.enum(['blog', 'market-report', 'origin-story', 'service']).optional(),
  locale: z.enum(['en', 'de', 'ja', 'vi']).optional(),
  status: z.enum(['draft', 'published', 'archived']).optional(),
  category: z.string().optional(),
  author: z.string().optional(),
  featured: z.boolean().optional(),
  dateFrom: z.string().optional(),
  dateTo: z.string().optional(),
  sortBy: z.enum(['relevance', 'date', 'title', 'author']).default('relevance'),
  sortOrder: z.enum(['asc', 'desc']).default('desc'),
  page: z.number().min(1).default(1),
  limit: z.number().min(1).max(100).default(10),
});

function getContentDirectory(type: string, locale: string): string {
  const baseDir = path.join(process.cwd(), 'content');

  switch (type) {
    case 'blog':
      return path.join(baseDir, 'blog', locale);
    case 'market-report':
      return path.join(baseDir, 'market-reports', locale);
    case 'origin-story':
      return path.join(baseDir, 'origin-stories', locale);
    case 'service':
      return path.join(baseDir, 'services', locale);
    default:
      throw new Error(`Invalid content type: ${type}`);
  }
}

function calculateRelevanceScore(content: any, query: string): number {
  const queryLower = query.toLowerCase();
  let score = 0;

  // Title match (highest weight)
  if (content.metadata.title?.toLowerCase().includes(queryLower)) {
    score += 10;
  }

  // Description match
  if (content.metadata.description?.toLowerCase().includes(queryLower)) {
    score += 5;
  }

  // Category match
  if (content.metadata.category?.toLowerCase().includes(queryLower)) {
    score += 3;
  }

  // Keywords match
  if (
    content.metadata.keywords?.some((keyword: string) =>
      keyword.toLowerCase().includes(queryLower)
    )
  ) {
    score += 3;
  }

  // Content match (lower weight due to potential noise)
  const contentMatches = (
    content.content.toLowerCase().match(new RegExp(queryLower, 'g')) || []
  ).length;
  score += Math.min(contentMatches * 0.5, 5); // Cap content matches at 5 points

  // Boost for exact matches
  if (content.metadata.title?.toLowerCase() === queryLower) {
    score += 20;
  }

  // Boost for featured content
  if (content.metadata.featured) {
    score += 2;
  }

  // Boost for published content
  if (content.metadata.status === 'published') {
    score += 1;
  }

  return score;
}

function highlightText(
  text: string,
  query: string,
  maxLength: number = 200
): string {
  if (!text || !query) return text?.substring(0, maxLength) || '';

  const queryLower = query.toLowerCase();
  const textLower = text.toLowerCase();
  const index = textLower.indexOf(queryLower);

  if (index === -1) {
    return text.substring(0, maxLength);
  }

  // Find a good starting point for the excerpt
  const start = Math.max(0, index - 50);
  const end = Math.min(text.length, start + maxLength);

  let excerpt = text.substring(start, end);

  // Add ellipsis if truncated
  if (start > 0) excerpt = '...' + excerpt;
  if (end < text.length) excerpt = excerpt + '...';

  // Highlight the query term
  const regex = new RegExp(`(${query})`, 'gi');
  excerpt = excerpt.replace(regex, '<mark>$1</mark>');

  return excerpt;
}

async function searchContent(searchParams: z.infer<typeof SearchSchema>) {
  const {
    query,
    type,
    locale,
    status,
    category,
    author,
    featured,
    dateFrom,
    dateTo,
    sortBy,
    sortOrder,
  } = searchParams;

  const contentTypes = type
    ? [type]
    : ['blog', 'market-report', 'origin-story', 'service'];
  const locales = locale ? [locale] : ['en', 'de', 'ja', 'vi'];
  const allContent = [];

  for (const contentType of contentTypes) {
    for (const loc of locales) {
      try {
        const contentDir = getContentDirectory(contentType, loc);
        const files = await fs.readdir(contentDir);

        for (const file of files) {
          if (file.endsWith('.mdx')) {
            const filePath = path.join(contentDir, file);
            const fileContent = await fs.readFile(filePath, 'utf-8');
            const { data: metadata, content } = matter(fileContent);

            // Type assertion for metadata to ensure all required properties are available
            const typedMetadata = {
              title: metadata.title || 'Untitled',
              description: metadata.description || '',
              status: metadata.status || 'draft',
              author: metadata.author || 'Unknown',
              featured: metadata.featured || false,
              category: metadata.category || 'uncategorized',
              locale: metadata.locale || loc,
              slug: metadata.slug || file.replace('.mdx', ''),
              ...metadata,
            } as any;

            const contentItem = {
              id: `${contentType}-${loc}-${file.replace('.mdx', '')}`,
              type: contentType,
              locale: loc,
              filename: file,
              metadata: typedMetadata,
              content,
              stats: {
                wordCount: content.split(/\s+/).filter(word => word.length > 0)
                  .length,
                lastModified: (await fs.stat(filePath)).mtime.toISOString(),
                size: (await fs.stat(filePath)).size,
              },
            };

            // Apply filters
            if (status && metadata.status !== status) continue;
            if (category && metadata.category !== category) continue;
            if (author && metadata.author !== author) continue;
            if (featured !== undefined && metadata.featured !== featured)
              continue;

            // Date range filter
            if (dateFrom || dateTo) {
              const contentDate = new Date(
                metadata.publishedAt || metadata.createdAt
              );
              if (dateFrom && contentDate < new Date(dateFrom)) continue;
              if (dateTo && contentDate > new Date(dateTo)) continue;
            }

            // Calculate relevance score
            const relevanceScore = calculateRelevanceScore(contentItem, query);

            // Only include if there's some relevance
            if (relevanceScore > 0) {
              allContent.push({
                ...contentItem,
                relevanceScore,
                excerpt: highlightText(content, query),
                titleHighlight: highlightText(metadata.title || '', query, 100),
                descriptionHighlight: highlightText(
                  metadata.description || '',
                  query,
                  200
                ),
              });
            }
          }
        }
      } catch (error) {
        // Directory read warning removed for production
      }
    }
  }

  // Sort results
  allContent.sort((a, b) => {
    switch (sortBy) {
      case 'relevance':
        return sortOrder === 'desc'
          ? b.relevanceScore - a.relevanceScore
          : a.relevanceScore - b.relevanceScore;
      case 'date':
        const dateA = new Date(
          a.metadata.publishedAt || a.metadata.createdAt || 0
        );
        const dateB = new Date(
          b.metadata.publishedAt || b.metadata.createdAt || 0
        );
        return sortOrder === 'desc'
          ? dateB.getTime() - dateA.getTime()
          : dateA.getTime() - dateB.getTime();
      case 'title':
        const titleA = a.metadata.title || '';
        const titleB = b.metadata.title || '';
        return sortOrder === 'desc'
          ? titleB.localeCompare(titleA)
          : titleA.localeCompare(titleB);
      case 'author':
        const authorA = a.metadata.author || '';
        const authorB = b.metadata.author || '';
        return sortOrder === 'desc'
          ? authorB.localeCompare(authorA)
          : authorA.localeCompare(authorB);
      default:
        return 0;
    }
  });

  return allContent;
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);

    const searchData = {
      query: searchParams.get('query') || '',
      type: searchParams.get('type') || undefined,
      locale: searchParams.get('locale') || undefined,
      status: searchParams.get('status') || undefined,
      category: searchParams.get('category') || undefined,
      author: searchParams.get('author') || undefined,
      featured:
        searchParams.get('featured') === 'true'
          ? true
          : searchParams.get('featured') === 'false'
            ? false
            : undefined,
      dateFrom: searchParams.get('dateFrom') || undefined,
      dateTo: searchParams.get('dateTo') || undefined,
      sortBy:
        (searchParams.get('sortBy') as
          | 'relevance'
          | 'date'
          | 'title'
          | 'author') || 'relevance',
      sortOrder: (searchParams.get('sortOrder') as 'asc' | 'desc') || 'desc',
      page: Math.max(1, parseInt(searchParams.get('page') || '1') || 1),
      limit: Math.max(
        1,
        Math.min(100, parseInt(searchParams.get('limit') || '10') || 10)
      ),
    };

    const validatedData = SearchSchema.parse(searchData);

    // Perform search
    const results = await searchContent(validatedData);

    // Apply pagination
    const { page, limit } = validatedData;
    const total = results.length;
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedResults = results.slice(startIndex, endIndex);

    // Generate search suggestions (simple implementation)
    const suggestions: string[] = [];
    if (results.length === 0 && validatedData.query.length > 2) {
      // Could implement fuzzy search or suggest similar terms
      suggestions.push(
        `Try searching for "${validatedData.query.substring(0, -1)}"`
      );
      suggestions.push('Check your spelling');
      suggestions.push('Try using different keywords');
    } else if (results.length > 0) {
      // Could add related search suggestions based on results
      // For now, just provide an empty array
    }

    return NextResponse.json({
      success: true,
      data: {
        results: paginatedResults,
        query: validatedData.query,
        filters: {
          type: validatedData.type,
          locale: validatedData.locale,
          status: validatedData.status,
          category: validatedData.category,
          author: validatedData.author,
          featured: validatedData.featured,
          dateFrom: validatedData.dateFrom,
          dateTo: validatedData.dateTo,
        },
        sorting: {
          sortBy: validatedData.sortBy,
          sortOrder: validatedData.sortOrder,
        },
        pagination: {
          page,
          limit,
          total,
          totalPages: Math.ceil(total / limit),
          hasNext: endIndex < total,
          hasPrev: page > 1,
        },
        suggestions,
        stats: {
          totalResults: total,
          searchTime: Date.now(), // Could implement actual timing
          topCategories: [
            ...new Set(results.slice(0, 20).map(r => r.metadata.category)),
          ].slice(0, 5),
          topAuthors: [
            ...new Set(results.slice(0, 20).map(r => r.metadata.author)),
          ].slice(0, 5),
        },
      },
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        {
          success: false,
          error: 'Invalid search parameters',
          details: error.issues,
        },
        { status: 400 }
      );
    }

    // Error logging removed for production
    return NextResponse.json(
      { success: false, error: 'Search failed' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const validatedData = SearchSchema.parse(body);

    // Perform search
    const results = await searchContent(validatedData);

    // Apply pagination
    const { page, limit } = validatedData;
    const total = results.length;
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedResults = results.slice(startIndex, endIndex);

    return NextResponse.json({
      success: true,
      data: {
        results: paginatedResults,
        query: validatedData.query,
        filters: {
          type: validatedData.type,
          locale: validatedData.locale,
          status: validatedData.status,
          category: validatedData.category,
          author: validatedData.author,
          featured: validatedData.featured,
          dateFrom: validatedData.dateFrom,
          dateTo: validatedData.dateTo,
        },
        sorting: {
          sortBy: validatedData.sortBy,
          sortOrder: validatedData.sortOrder,
        },
        pagination: {
          page,
          limit,
          total,
          totalPages: Math.ceil(total / limit),
          hasNext: endIndex < total,
          hasPrev: page > 1,
        },
        stats: {
          totalResults: total,
          searchTime: Date.now(),
          topCategories: [
            ...new Set(results.slice(0, 20).map(r => r.metadata.category)),
          ].slice(0, 5),
          topAuthors: [
            ...new Set(results.slice(0, 20).map(r => r.metadata.author)),
          ].slice(0, 5),
        },
      },
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        {
          success: false,
          error: 'Invalid search parameters',
          details: error.issues,
        },
        { status: 400 }
      );
    }

    // Error logging removed for production
    return NextResponse.json(
      { success: false, error: 'Search failed' },
      { status: 500 }
    );
  }
}

import fs from 'fs/promises';
import path from 'path';

import matter from 'gray-matter';

import { NextRequest, NextResponse } from 'next/server';

function getContentDirectory(type: string, locale: string): string {
  const baseDir = path.join(process.cwd(), 'content');

  switch (type) {
    case 'blog':
      return path.join(baseDir, 'blog', locale);
    case 'market-report':
      return path.join(baseDir, 'market-reports', locale);
    case 'origin-story':
      return path.join(baseDir, 'origin-stories', locale);
    case 'service':
      return path.join(baseDir, 'services', locale);
    default:
      throw new Error(`Invalid content type: ${type}`);
  }
}

async function getContentStats() {
  const contentTypes = ['blog', 'market-report', 'origin-story', 'service'];
  const locales = ['en', 'es', 'fr', 'pt'];

  interface ContentTypeStats {
    total: number;
    published: number;
    draft: number;
    archived: number;
    featured: number;
  }

  interface RecentActivityItem {
    id: string;
    type: string;
    locale: string;
    title: string;
    status: string;
    author: string;
    lastModified: string;
    action: string;
  }

  const stats = {
    overview: {
      totalContent: 0,
      publishedContent: 0,
      draftContent: 0,
      archivedContent: 0,
      featuredContent: 0,
    },
    byType: {} as Record<string, ContentTypeStats>,
    byLocale: {} as Record<string, ContentTypeStats>,
    byStatus: {
      draft: 0,
      published: 0,
      archived: 0,
    },
    byAuthor: {} as Record<string, number>,
    byCategory: {} as Record<string, number>,
    recentActivity: [] as RecentActivityItem[],
    contentHealth: {
      withImages: 0,
      withoutImages: 0,
      withSEO: 0,
      withoutSEO: 0,
      averageWordCount: 0,
      totalWordCount: 0,
    },
    publishingTrends: {
      thisMonth: 0,
      lastMonth: 0,
      thisYear: 0,
      lastYear: 0,
    },
  };

  const allContent = [];
  const now = new Date();
  const thisMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  const thisYear = new Date(now.getFullYear(), 0, 1);
  const lastYear = new Date(now.getFullYear() - 1, 0, 1);

  // Initialize type and locale stats
  for (const type of contentTypes) {
    stats.byType[type] = {
      total: 0,
      published: 0,
      draft: 0,
      archived: 0,
      featured: 0,
    };
  }

  for (const locale of locales) {
    stats.byLocale[locale] = {
      total: 0,
      published: 0,
      draft: 0,
      archived: 0,
      featured: 0,
    };
  }

  // Collect all content
  for (const contentType of contentTypes) {
    for (const locale of locales) {
      try {
        const contentDir = getContentDirectory(contentType, locale);
        const files = await fs.readdir(contentDir);

        for (const file of files) {
          if (file.endsWith('.mdx')) {
            const filePath = path.join(contentDir, file);
            const fileContent = await fs.readFile(filePath, 'utf-8');
            const { data: metadata, content } = matter(fileContent);

            // Type assertion for metadata to ensure all required properties are available
            const typedMetadata = {
              title: metadata.title || 'Untitled',
              description: metadata.description || '',
              status: metadata.status || 'draft',
              author: metadata.author || 'Unknown',
              featured: metadata.featured || false,
              category: metadata.category || 'uncategorized',
              locale: metadata.locale || locale,
              slug: metadata.slug || file.replace('.mdx', ''),
              ...metadata,
            } as any;
            const fileStat = await fs.stat(filePath);

            const contentItem = {
              id: `${contentType}-${locale}-${file.replace('.mdx', '')}`,
              type: contentType,
              locale,
              filename: file,
              metadata: typedMetadata,
              content,
              stats: {
                wordCount: content.split(/\s+/).filter(word => word.length > 0)
                  .length,
                lastModified: fileStat.mtime.toISOString(),
                size: fileStat.size,
              },
            };

            allContent.push(contentItem);

            // Update overview stats
            stats.overview.totalContent++;

            const status = typedMetadata.status;
            if (status === 'published') stats.overview.publishedContent++;
            else if (status === 'draft') stats.overview.draftContent++;
            else if (status === 'archived') stats.overview.archivedContent++;

            if (typedMetadata.featured) stats.overview.featuredContent++;

            // Update by type stats
            stats.byType[contentType]!.total++;
            if (status === 'published') stats.byType[contentType]!.published++;
            else if (status === 'draft') stats.byType[contentType]!.draft++;
            else if (status === 'archived')
              stats.byType[contentType]!.archived++;
            if (typedMetadata.featured) stats.byType[contentType]!.featured++;

            // Update by locale stats
            stats.byLocale[locale]!.total++;
            if (status === 'published') stats.byLocale[locale]!.published++;
            else if (status === 'draft') stats.byLocale[locale]!.draft++;
            else if (status === 'archived') stats.byLocale[locale]!.archived++;
            if (typedMetadata.featured) stats.byLocale[locale]!.featured++;

            // Update by status stats
            stats.byStatus[status as keyof typeof stats.byStatus]++;

            // Update by author stats
            const author = typedMetadata.author;
            stats.byAuthor[author] = (stats.byAuthor[author] || 0) + 1;

            // Update by category stats
            const category = typedMetadata.category;
            stats.byCategory[category] = (stats.byCategory[category] || 0) + 1;

            // Update content health stats
            stats.contentHealth.totalWordCount += contentItem.stats.wordCount;

            if (metadata.coverImage) {
              stats.contentHealth.withImages++;
            } else {
              stats.contentHealth.withoutImages++;
            }

            if (metadata.seoTitle && metadata.seoDescription) {
              stats.contentHealth.withSEO++;
            } else {
              stats.contentHealth.withoutSEO++;
            }

            // Update publishing trends
            const publishDate = new Date(
              metadata.publishedAt || metadata.createdAt || fileStat.mtime
            );

            if (publishDate >= thisMonth) {
              stats.publishingTrends.thisMonth++;
            } else if (publishDate >= lastMonth && publishDate < thisMonth) {
              stats.publishingTrends.lastMonth++;
            }

            if (publishDate >= thisYear) {
              stats.publishingTrends.thisYear++;
            } else if (publishDate >= lastYear && publishDate < thisYear) {
              stats.publishingTrends.lastYear++;
            }
          }
        }
      } catch (error) {
        // Directory read error - could be logged to external service in production
      }
    }
  }

  // Calculate average word count
  if (stats.overview.totalContent > 0) {
    stats.contentHealth.averageWordCount = Math.round(
      stats.contentHealth.totalWordCount / stats.overview.totalContent
    );
  }

  // Get recent activity (last 10 modified items)
  stats.recentActivity = allContent
    .sort(
      (a, b) =>
        new Date(b.stats.lastModified).getTime() -
        new Date(a.stats.lastModified).getTime()
    )
    .slice(0, 10)
    .map(item => ({
      id: item.id,
      type: item.type,
      locale: item.locale,
      title: item.metadata.title,
      status: item.metadata.status,
      author: item.metadata.author || 'Unknown',
      lastModified: item.stats.lastModified,
      action: 'modified', // Could be enhanced to track actual actions
    }));

  // Sort authors and categories by count
  const sortedAuthors = Object.entries(stats.byAuthor)
    .sort(([, a], [, b]) => b - a)
    .slice(0, 10);

  const sortedCategories = Object.entries(stats.byCategory)
    .sort(([, a], [, b]) => b - a)
    .slice(0, 10);

  stats.byAuthor = Object.fromEntries(sortedAuthors);
  stats.byCategory = Object.fromEntries(sortedCategories);

  return stats;
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const type = searchParams.get('type');
    const locale = searchParams.get('locale');
    const timeframe = searchParams.get('timeframe') || 'all'; // all, month, year

    const stats = await getContentStats();

    // Filter stats if specific type or locale requested
    let filteredStats = stats;

    if (type && stats.byType[type]) {
      filteredStats = {
        ...stats,
        overview: {
          totalContent: stats.byType[type].total,
          publishedContent: stats.byType[type].published,
          draftContent: stats.byType[type].draft,
          archivedContent: stats.byType[type].archived,
          featuredContent: stats.byType[type].featured,
        },
        recentActivity: stats.recentActivity.filter(item => item.type === type),
      };
    }

    if (locale && stats.byLocale[locale]) {
      filteredStats = {
        ...filteredStats,
        overview: {
          totalContent: stats.byLocale[locale].total,
          publishedContent: stats.byLocale[locale].published,
          draftContent: stats.byLocale[locale].draft,
          archivedContent: stats.byLocale[locale].archived,
          featuredContent: stats.byLocale[locale].featured,
        },
        recentActivity: filteredStats.recentActivity.filter(
          item => item.locale === locale
        ),
      };
    }

    return NextResponse.json({
      success: true,
      data: {
        stats: filteredStats,
        filters: {
          type,
          locale,
          timeframe,
        },
        generatedAt: new Date().toISOString(),
        summary: {
          totalContent: filteredStats.overview.totalContent,
          publishedPercentage:
            filteredStats.overview.totalContent > 0
              ? Math.round(
                  (filteredStats.overview.publishedContent /
                    filteredStats.overview.totalContent) *
                    100
                )
              : 0,
          featuredPercentage:
            filteredStats.overview.totalContent > 0
              ? Math.round(
                  (filteredStats.overview.featuredContent /
                    filteredStats.overview.totalContent) *
                    100
                )
              : 0,
          averageWordCount: filteredStats.contentHealth.averageWordCount,
          topAuthor: Object.keys(filteredStats.byAuthor)[0] || null,
          topCategory: Object.keys(filteredStats.byCategory)[0] || null,
          monthlyGrowth:
            stats.publishingTrends.lastMonth > 0
              ? Math.round(
                  ((stats.publishingTrends.thisMonth -
                    stats.publishingTrends.lastMonth) /
                    stats.publishingTrends.lastMonth) *
                    100
                )
              : 0,
        },
      },
    });
  } catch (error) {
    // Error logging removed for production
    return NextResponse.json(
      { success: false, error: 'Failed to generate content statistics' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
