const logger = createScopedLogger('SEOAuditAPI');

// Rate limiting (simple in-memory store)
const auditRequests = new Map<string, number[]>();
const RATE_LIMIT = 10; // requests per hour
const RATE_WINDOW = 60 * 60 * 1000; // 1 hour in milliseconds

function isRateLimited(ip: string): boolean {
  const now = Date.now();
  const requests = auditRequests.get(ip) || [];

  // Remove old requests outside the window
  const recentRequests = requests.filter(time => now - time < RATE_WINDOW);

  if (recentRequests.length >= RATE_LIMIT) {
    return true;
  }

  // Add current request
  recentRequests.push(now);
  auditRequests.set(ip, recentRequests);

  return false;
}

// Type for structured data objects
type StructuredDataObject = Record<string, unknown>;

/**
 * POST /api/seo/audit
 *
 * Perform SEO audit on a page or content
 *
 * Body:
 * {
 *   url: string;
 *   content?: string;
 *   metadata?: Metadata;
 *   structuredData?: StructuredDataObject[];
 *   config?: Partial<SEOAuditConfig>;
 * }
 */
export async function POST(request: NextRequest) {
  try {
    // Rate limiting
    const headersList = await headers();
    const ip =
      headersList.get('x-forwarded-for') ||
      headersList.get('x-real-ip') ||
      'unknown';

    if (isRateLimited(ip)) {
      return NextResponse.json(
        {
          error: 'Rate limit exceeded',
          message: 'Too many audit requests. Please try again later.',
        },
        { status: 429 }
      );
    }

    const body = await request.json();
    const {
      url,
      content,
      metadata,
      structuredData,
      config: _config,
      format = 'json',
    } = body;

    // Validate required fields
    if (!url) {
      return NextResponse.json({ error: 'URL is required' }, { status: 400 });
    }

    // Validate URL format
    try {
      new URL(url);
    } catch {
      return NextResponse.json(
        { error: 'Invalid URL format' },
        { status: 400 }
      );
    }

    // Perform SEO audit
    const auditResult = await seoAuditManager.auditPage(
      url,
      metadata,
      content,
      structuredData
    );

    // Return different formats based on request
    if (format === 'report') {
      const report = generateSEOReport(auditResult);
      return new NextResponse(report, {
        headers: {
          'Content-Type': 'text/markdown',
          'Content-Disposition': `attachment; filename="seo-audit-${new Date().toISOString().split('T')[0]}.md"`,
        },
      });
    }

    return NextResponse.json({
      success: true,
      audit: auditResult,
      timestamp: new Date().toISOString(),
      url,
    });
  } catch (error) {
    // Error logging removed for production
    return NextResponse.json(
      {
        error: 'Internal server error',
        message: 'Failed to perform SEO audit',
      },
      { status: 500 }
    );
  }
}

