/**
 * PUT /api/seo/audit/batch
 *
 * Batch SEO audit for multiple URLs
 */
export async function PUT(request: NextRequest) {
  try {
    // Rate limiting (stricter for batch operations)
    const headersList = await headers();
    const ip =
      headersList.get('x-forwarded-for') ||
      headersList.get('x-real-ip') ||
      'unknown';

    if (isRateLimited(ip)) {
      return NextResponse.json(
        {
          error: 'Rate limit exceeded',
          message: 'Too many audit requests. Please try again later.',
        },
        { status: 429 }
      );
    }

    const body = await request.json();
    const { urls, config: _config } = body;

    // Validate input
    if (!Array.isArray(urls) || urls.length === 0) {
      return NextResponse.json(
        { error: 'URLs array is required' },
        { status: 400 }
      );
    }

    if (urls.length > 10) {
      return NextResponse.json(
        { error: 'Maximum 10 URLs allowed per batch' },
        { status: 400 }
      );
    }

    // Validate all URLs
    for (const url of urls) {
      try {
        new URL(url);
      } catch {
        return NextResponse.json(
          { error: `Invalid URL format: ${url}` },
          { status: 400 }
        );
      }
    }

    // Perform batch audit
    const results = await Promise.allSettled(
      urls.map(async (url: string) => {
        const audit = await seoAuditManager.auditPage(url);
        return { url, audit };
      })
    );

    const successful = results
      .filter(
        (result): result is PromiseFulfilledResult<any> =>
          result.status === 'fulfilled'
      )
      .map(result => result.value);

    const failed = results
      .filter(
        (result): result is PromiseRejectedResult =>
          result.status === 'rejected'
      )
      .map((result, index) => ({
        url: urls[index],
        error: result.reason?.message || 'Unknown error',
      }));

    // Calculate batch statistics
    const scores = successful.map(result => result.audit.score);
    const averageScore =
      scores.length > 0
        ? scores.reduce((sum, score) => sum + score, 0) / scores.length
        : 0;

    const totalIssues = successful.reduce(
      (sum, result) => sum + result.audit.issues.length,
      0
    );

    return NextResponse.json({
      success: true,
      summary: {
        totalUrls: urls.length,
        successful: successful.length,
        failed: failed.length,
        averageScore: Math.round(averageScore),
        totalIssues,
      },
      results: successful,
      failures: failed,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    // API error logging removed for production
    return NextResponse.json(
      {
        error: 'Internal server error',
        message: 'Failed to perform batch SEO audit',
      },
      { status: 500 }
    );
  }
}

