        'Dak Lak',
        'Gia Lai',
        'Premium',
        'Specialty',
        'Instant Coffee',
        'Green Beans',
      ];

      return popularTerms;
    } catch (error) {
      // Application layer error logging removed for production
      return [];
    }
  }
}

