export class SEOService implements ISEOService {
  private logger = createScopedLogger('SEOService');
  private baseUrl =
    process.env.NEXT_PUBLIC_BASE_URL || 'https://greatbeans.com';

  async generateMetadata(
    page: string,
    data: Record<string, any> = {}
  ): Promise<SEOMetadata> {
    try {
      const metadata: SEOMetadata = {
        title: this.generateTitle(page, data),
        description: this.generateDescription(page, data),
        keywords: this.generateKeywords(page, data),
        canonical: `${this.baseUrl}${page}`,
        ogTitle: this.generateTitle(page, data),
        ogDescription: this.generateDescription(page, data),
        ogImage: this.generateOGImage(page, data),
        ogType: 'website',
        twitterCard: 'summary_large_image',
        twitterTitle: this.generateTitle(page, data),
        twitterDescription: this.generateDescription(page, data),
        twitterImage: this.generateOGImage(page, data),
      };

      // Add structured data if applicable
      if (data.product) {
        metadata.structuredData = await this.generateStructuredData(
          'Product',
          data.product
        );
      } else if (data.service) {
        metadata.structuredData = await this.generateStructuredData(
          'Service',
          data.service
        );
      } else if (data.organization) {
        metadata.structuredData = await this.generateStructuredData(
          'Organization',
          data.organization
        );
      }

      return metadata;
    } catch (error) {
      // Application layer error logging removed for production
      return this.getDefaultMetadata();
    }
  }

  async generateStructuredData(
    type: string,
    data: Record<string, any>
  ): Promise<Record<string, any>> {
    try {
      const baseStructure = {
        '@context': 'https://schema.org',
        '@type': type,
      };

      switch (type) {
        case 'Product':
          return {
            ...baseStructure,
            name: data.name,
            description: data.description,
            image: data.image,
            brand: {
              '@type': 'Brand',
              name: 'The Great Beans',
            },
            offers: {
              '@type': 'Offer',
              price: data.price,
              priceCurrency: data.currency || 'USD',
              availability: 'https://schema.org/InStock',
            },
            category: data.category,
            origin: data.origin,
          };

        case 'Service':
          return {
            ...baseStructure,
            name: data.name,
            description: data.description,
            provider: {
              '@type': 'Organization',
              name: 'The Great Beans',
            },
            serviceType: data.serviceType,
            areaServed: 'Worldwide',
          };

        case 'Organization':
          return {
            ...baseStructure,
            name: 'The Great Beans',
            description: 'Premium Vietnamese Coffee Exporter',
            url: this.baseUrl,
            logo: `${this.baseUrl}/logo.png`,
            contactPoint: {
              '@type': 'ContactPoint',
              telephone: '+84-xxx-xxx-xxx',
              contactType: 'Customer Service',
              email: 'info@greatbeans.com',
            },
            address: {
              '@type': 'PostalAddress',
              addressCountry: 'VN',
              addressRegion: 'Ho Chi Minh City',
            },
            sameAs: [
              'https://linkedin.com/company/greatbeans',
              'https://facebook.com/greatbeans',
            ],
          };

        default:
          return baseStructure;
      }
    } catch (error) {
      // Application layer error logging removed for production
      return {};
    }
  }

  async generateSitemap(): Promise<string[]> {
    try {
      const urls = [
        '/',
        '/products',
        '/services',
        '/about',
        '/contact',
        '/blog',
        '/certifications',
      ];

      // Add dynamic product URLs (in a real implementation, fetch from database)
      const productSlugs = [
        'robusta-premium',
        'arabica-specialty',
        'instant-coffee',
      ];
      productSlugs.forEach(slug => {
        urls.push(`/products/${slug}`);
      });

      // Add service URLs
      const serviceSlugs = [
        'oem-manufacturing',
        'private-label',
        'sourcing-consulting',
      ];
      serviceSlugs.forEach(slug => {
        urls.push(`/services/${slug}`);
      });

      return urls.map(url => `${this.baseUrl}${url}`);
    } catch (error) {
      // Application layer error logging removed for production
      return [];
    }
  }

  async validateMetadata(metadata: SEOMetadata): Promise<boolean> {
    try {
      const issues: string[] = [];

      // Title validation
      if (!metadata.title) {
        issues.push('Title is required');
      } else if (metadata.title.length > 60) {
        issues.push('Title is too long (max 60 characters)');
      }

      // Description validation
      if (!metadata.description) {
        issues.push('Description is required');
      } else if (metadata.description.length > 160) {
        issues.push('Description is too long (max 160 characters)');
      }

      // Keywords validation
      if (metadata.keywords && metadata.keywords.length > 10) {
        issues.push('Too many keywords (max 10)');
      }

      if (issues.length > 0) {
        // Application layer warning logging removed for production
        return false;
      }

      return true;
    } catch (error) {
      // Application layer error logging removed for production
      return false;
    }
  }

  private generateTitle(page: string, data: Record<string, any>): string {
    const baseTitle = 'The Great Beans';

    switch (page) {
