                    />
                    <span className="text-gray-500">{factor.probability}%</span>
                  </div>
                  <div>
                    <label className="mb-1 block text-gray-600">
                      Impact (%)
                    </label>
                    <input
                      type="range"
                      min="0"
                      max="100"
                      value={factor.impact}
                      onChange={e =>
                        updateFactorValue(
                          factor.id,
                          'impact',
                          parseInt(e.target.value)
                        )
                      }
