                      type="range"
                      min="1"
                      max="10"
                      value={factor.weight}
                      onChange={e =>
                        updateFactorValue(
                          factor.id,
                          'weight',
                          parseInt(e.target.value)
                        )
                      }
                      className="w-full"
                    />
                    <span className="text-gray-500">{factor.weight}/10</span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

'use client';

import {
  Calculator,
  TrendingDown,
  Package,
  DollarSign,
  Truck,
  Calendar,
  AlertCircle,
  CheckCircle,
  Download,
  Share2,
} from 'lucide-react';
import React, { useState, useEffect } from 'react';

import { type CatalogProduct } from '@/data/product-catalog';
import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import { Card, CardContent } from '@/presentation/components/ui/card';
import { Input } from '@/presentation/components/ui/input';
import { Label } from '@/presentation/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/presentation/components/ui/select';
import { SectionHeading } from '@/shared/components/design-system/Typography/Heading';

interface BulkPricingCalculatorProps {
  product: CatalogProduct;
  className?: string;
}

interface PricingCalculation {
  quantity: number;
  unitPrice: number;
  totalPrice: number;
  discountPercent: number;
  discountAmount: number;
  estimatedShipping: number;
  totalWithShipping: number;
  leadTime: number;
  paymentTerms: string;
}

export function BulkPricingCalculator({
  product,
  className,
}: BulkPricingCalculatorProps) {
  const [quantity, setQuantity] = useState<number>(
    product.pricing.minimumOrder
  );
  const [selectedUnit, setSelectedUnit] = useState<string>('MT');
  const [selectedIncoterm, setSelectedIncoterm] = useState<string>('FOB');
  const [calculation, setCalculation] = useState<PricingCalculation | null>(
    null
  );
  const [showBreakdown, setShowBreakdown] = useState(false);

  // Convert quantity to base unit (MT) for calculations
  const getQuantityInMT = (qty: number, unit: string): number => {
    switch (unit) {
      case 'MT':
        return qty;
      case 'kg':
        return qty / 1000;
      case 'lbs':
        return qty / 2204.62;
      case 'containers':
        return qty * 18; // Assuming 18 MT per container
      default:
        return qty;
    }
  };

  // Calculate pricing based on quantity and discounts
  const calculatePricing = (qty: number, unit: string): PricingCalculation => {
    const quantityInMT = getQuantityInMT(qty, unit);

    // Find applicable discount tier
    let discountPercent = 0;
    if (product.pricing.discountTiers) {
      const applicableTier = product.pricing.discountTiers
        .filter(tier => quantityInMT >= tier.minQuantity)
        .sort((a, b) => b.discountPercent - a.discountPercent)[0];

      if (applicableTier) {
        discountPercent = applicableTier.discountPercent;
      }
    }

    const unitPrice = product.pricing.basePrice * (1 - discountPercent / 100);
    const totalPrice = unitPrice * quantityInMT;
    const discountAmount =
      (product.pricing.basePrice - unitPrice) * quantityInMT;

    // Estimate shipping costs based on Incoterms and quantity
    let estimatedShipping = 0;
    if (selectedIncoterm === 'CIF' || selectedIncoterm === 'CFR') {
      estimatedShipping = quantityInMT * 150; // $150 per MT for shipping
    } else if (selectedIncoterm === 'DDP') {
      estimatedShipping = quantityInMT * 250; // $250 per MT for full delivery
    }

    // Adjust lead time based on quantity
    let leadTime = product.availability.leadTime;
    if (quantityInMT > 100) {
      leadTime += 7; // Additional week for large orders
    }

    return {
      quantity: quantityInMT,
      unitPrice,
      totalPrice,
      discountPercent,
      discountAmount,
      estimatedShipping,
      totalWithShipping: totalPrice + estimatedShipping,
      leadTime,
      paymentTerms: product.pricing.paymentTerms,
    };
  };

  useEffect(() => {
    if (quantity > 0) {
      const calc = calculatePricing(quantity, selectedUnit);
      setCalculation(calc);
    }
  }, [quantity, selectedUnit, selectedIncoterm, product]);

  const handleQuantityChange = (value: string) => {
    const numValue = parseFloat(value);
    if (!isNaN(numValue) && numValue >= 0) {
      setQuantity(numValue);
    }
  };

  const isValidOrder =
    calculation && calculation.quantity >= product.pricing.minimumOrder;

  const exportQuote = () => {
    if (!calculation) return;

    const quoteData = {
      product: product.name,
      quantity: `${quantity} ${selectedUnit}`,
      unitPrice: `$${calculation.unitPrice.toFixed(2)}`,
      totalPrice: `$${calculation.totalPrice.toLocaleString()}`,
      discount: `${calculation.discountPercent}%`,
      incoterms: selectedIncoterm,
      leadTime: `${calculation.leadTime} days`,
      validUntil: product.pricing.priceValidUntil,
    };

    // In a real app, this would generate a PDF or send to CRM
    // Quote export tracking removed for production
    alert(
      'Quote exported! In production, this would generate a PDF or send to your CRM.'
    );
  };

  return (
    <Card className={`shadow-lg ${className}`}>
      <CardContent className="p-6">
        <SectionHeading size="lg" className="mb-6 text-coffee-800">
          <div className="flex items-center">
            <Calculator className="mr-3 h-6 w-6" />
            Bulk Pricing Calculator
          </div>
        </SectionHeading>

        {/* Input Controls */}
        <div className="mb-6 grid grid-cols-1 gap-4 md:grid-cols-3">
          <div>
            <Label
              htmlFor="quantity"
              className="text-sm font-medium text-coffee-700"
            >
              Quantity
            </Label>
            <Input
              id="quantity"
              type="number"
              value={quantity}
              onChange={e => handleQuantityChange(e.target.value)}
              min={0}
              step={selectedUnit === 'kg' ? 100 : 1}
              className="mt-1"
            />
          </div>

          <div>
            <Label
              htmlFor="unit"
              className="text-sm font-medium text-coffee-700"
            >
              Unit
            </Label>
            <Select value={selectedUnit} onValueChange={setSelectedUnit}>
              <SelectTrigger className="mt-1">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="MT">Metric Tons (MT)</SelectItem>
                <SelectItem value="kg">Kilograms (kg)</SelectItem>
                <SelectItem value="lbs">Pounds (lbs)</SelectItem>
                <SelectItem value="containers">Containers (20ft)</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label
              htmlFor="incoterms"
              className="text-sm font-medium text-coffee-700"
            >
              Incoterms
            </Label>
            <Select
              value={selectedIncoterm}
              onValueChange={setSelectedIncoterm}
            >
              <SelectTrigger className="mt-1">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="FOB">FOB (Free on Board)</SelectItem>
                <SelectItem value="CFR">CFR (Cost and Freight)</SelectItem>
                <SelectItem value="CIF">
                  CIF (Cost, Insurance, Freight)
                </SelectItem>
                <SelectItem value="DDP">DDP (Delivered Duty Paid)</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>

        {/* Validation Alert */}
        {calculation && !isValidOrder && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 p-4">
            <div className="flex items-center">
              <AlertCircle className="mr-3 h-5 w-5 text-red-600" />
              <div>
                <h4 className="text-sm font-semibold text-red-800">
                  Minimum Order Required
                </h4>
                <p className="text-xs text-red-700">
                  Minimum order quantity is {product.pricing.minimumOrder} MT.
                  Current quantity: {calculation.quantity.toFixed(2)} MT
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Pricing Results */}
        {calculation && isValidOrder && (
          <div className="space-y-4">
            {/* Main Pricing Display */}
            <div className="rounded-lg border border-green-200 bg-gradient-to-r from-green-50 to-emerald-50 p-6">
              <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                <div>
                  <div className="mb-2 flex items-center justify-between">
                    <span className="text-sm font-medium text-green-700">
                      Unit Price
                    </span>
                    {calculation.discountPercent > 0 && (
                      <Badge
                        variant="secondary"
                        className="bg-green-100 text-green-800"
                      >
                        <TrendingDown className="mr-1 h-3 w-3" />
                        {calculation.discountPercent}% OFF
                      </Badge>
                    )}
                  </div>
                  <p className="text-2xl font-bold text-green-800">
                    ${calculation.unitPrice.toFixed(2)}/MT
                  </p>
                  {calculation.discountPercent > 0 && (
                    <p className="text-sm text-green-600 line-through">
                      ${product.pricing.basePrice.toFixed(2)}/MT
                    </p>
                  )}
                </div>

                <div>
                  <span className="text-sm font-medium text-green-700">
                    Total Price
                  </span>
                  <p className="text-2xl font-bold text-green-800">
                    ${calculation.totalPrice.toLocaleString()}
                  </p>
                  {calculation.discountAmount > 0 && (
                    <p className="text-sm text-green-600">
                      You save: ${calculation.discountAmount.toLocaleString()}
                    </p>
                  )}
                </div>
              </div>
            </div>

            {/* Detailed Breakdown */}
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">
              <div className="rounded-lg border border-blue-200 bg-blue-50 p-4">
                <div className="mb-2 flex items-center justify-between">
                  <Package className="h-5 w-5 text-blue-600" />
                  <span className="text-xs font-medium text-blue-700">
                    QUANTITY
                  </span>
                </div>
                <p className="text-lg font-bold text-blue-800">
                  {calculation.quantity.toFixed(2)} MT
                </p>
                <p className="text-xs text-blue-600">
                  {quantity} {selectedUnit}
                </p>
              </div>

              <div className="rounded-lg border border-purple-200 bg-purple-50 p-4">
                <div className="mb-2 flex items-center justify-between">
                  <Calendar className="h-5 w-5 text-purple-600" />
                  <span className="text-xs font-medium text-purple-700">
                    LEAD TIME
                  </span>
                </div>
                <p className="text-lg font-bold text-purple-800">
                  {calculation.leadTime} days
                </p>
                <p className="text-xs text-purple-600">
                  {calculation.paymentTerms}
                </p>
              </div>

              {calculation.estimatedShipping > 0 && (
                <div className="rounded-lg border border-orange-200 bg-orange-50 p-4">
                  <div className="mb-2 flex items-center justify-between">
                    <Truck className="h-5 w-5 text-orange-600" />
                    <span className="text-xs font-medium text-orange-700">
                      SHIPPING
                    </span>
                  </div>
                  <p className="text-lg font-bold text-orange-800">
                    ${calculation.estimatedShipping.toLocaleString()}
                  </p>
                  <p className="text-xs text-orange-600">
                    {selectedIncoterm} terms
                  </p>
                </div>
              )}

              <div className="rounded-lg border border-gold-200 bg-gold-50 p-4">
                <div className="mb-2 flex items-center justify-between">
                  <DollarSign className="h-5 w-5 text-gold-600" />
                  <span className="text-xs font-medium text-gold-700">
                    TOTAL
                  </span>
                </div>
                <p className="text-lg font-bold text-gold-800">
                  ${calculation.totalWithShipping.toLocaleString()}
                </p>
                <p className="text-xs text-gold-600">Including all costs</p>
              </div>
            </div>

            {/* Action Buttons */}
            <div className="flex flex-col gap-3 sm:flex-row">
              <Button
                onClick={exportQuote}
                className="flex-1 bg-coffee-600 hover:bg-coffee-700"
              >
                <Download className="mr-2 h-4 w-4" />
                Export Quote
              </Button>

              <Button
                variant="outline"
                onClick={() => setShowBreakdown(!showBreakdown)}
                className="flex-1"
              >
                <Calculator className="mr-2 h-4 w-4" />
                {showBreakdown ? 'Hide' : 'Show'} Breakdown
              </Button>

              <Button
                variant="outline"
                onClick={() => {
                  navigator.share?.({
                    title: `${product.name} - Bulk Quote`,
                    text: `Quote for ${quantity} ${selectedUnit} at $${calculation.unitPrice.toFixed(2)}/MT`,
                    url: window.location.href,
                  });
                }}
              >
                <Share2 className="mr-2 h-4 w-4" />
                Share
              </Button>
            </div>

            {/* Detailed Breakdown */}
            {showBreakdown && (
              <Card className="bg-gray-50">
                <CardContent className="p-4">
                  <h4 className="mb-3 text-sm font-semibold text-coffee-800">
                    Price Breakdown
                  </h4>
                  <div className="space-y-2 text-sm">
                    <div className="flex justify-between">
                      <span className="text-gray-600">
                        Base Price ({calculation.quantity.toFixed(2)} MT × $
                        {product.pricing.basePrice})
                      </span>
                      <span className="text-gray-800">
                        $
                        {(
                          calculation.quantity * product.pricing.basePrice
                        ).toLocaleString()}
                      </span>
                    </div>
                    {calculation.discountAmount > 0 && (
                      <div className="flex justify-between text-green-600">
                        <span>
                          Volume Discount ({calculation.discountPercent}%)
                        </span>
                        <span>
                          -${calculation.discountAmount.toLocaleString()}
                        </span>
                      </div>
                    )}
                    <div className="flex justify-between border-t pt-2 font-medium">
                      <span className="text-gray-800">Product Total</span>
                      <span className="text-gray-800">
                        ${calculation.totalPrice.toLocaleString()}
                      </span>
                    </div>
                    {calculation.estimatedShipping > 0 && (
                      <>
                        <div className="flex justify-between">
                          <span className="text-gray-600">
                            Estimated Shipping ({selectedIncoterm})
                          </span>
                          <span className="text-gray-800">
                            ${calculation.estimatedShipping.toLocaleString()}
                          </span>
                        </div>
                        <div className="flex justify-between border-t pt-2 font-bold text-coffee-800">
                          <span>Grand Total</span>
                          <span>
                            ${calculation.totalWithShipping.toLocaleString()}
                          </span>
                        </div>
                      </>
                    )}
                  </div>
                </CardContent>
              </Card>
            )}

            {/* Additional Information */}
            <div className="rounded-lg border border-blue-200 bg-blue-50 p-4">
              <div className="flex items-start">
                <CheckCircle className="mr-3 mt-0.5 h-5 w-5 flex-shrink-0 text-blue-600" />
                <div>
                  <h4 className="text-sm font-semibold text-blue-800">
                    Quote Valid Until
                  </h4>
                  <p className="text-xs text-blue-700">
                    This quote is valid until{' '}
                    {new Date(
                      product.pricing.priceValidUntil
                    ).toLocaleDateString()}
                    . Prices are subject to market conditions and availability.
                  </p>
                </div>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

'use client';

import React, { useState, useMemo } from 'react';

interface Column<T = Record<string, unknown>> {
  key: keyof T | string;
  label: string;
  type?: 'text' | 'number' | 'currency' | 'percentage' | 'date';
  sortable?: boolean;
  width?: string;
  align?: 'left' | 'center' | 'right';
  format?: (value: unknown) => string;
  currency?: string;
  precision?: number;
}

interface DataTableProps<T = Record<string, unknown>> {
  data: T[];
  columns: Column<T>[];
  title?: string;
  searchable?: boolean;
  sortable?: boolean;
  exportable?: boolean;
  pageSize?: number;
  className?: string;
  striped?: boolean;
  compact?: boolean;
  showRowNumbers?: boolean;
}

export const DataTable = <
  T extends Record<string, unknown> = Record<string, unknown>,
>(
  props: DataTableProps<T>
) => {
  const {
    data,
    columns,
    title,
    searchable = true,
    sortable = true,
    exportable = false,
    pageSize = 10,
    className = '',
    striped = true,
    compact = false,
    showRowNumbers = false,
  } = props;
  const [searchTerm, setSearchTerm] = useState('');
  const [sortConfig, setSortConfig] = useState<{
    key: string;
    direction: 'asc' | 'desc';
  } | null>(null);
  const [currentPage, setCurrentPage] = useState(1);

  // Filter data based on search term
  const filteredData = useMemo(() => {
    if (!searchTerm) return data;

    return data.filter(row =>
      Object.values(row).some(value =>
        String(value).toLowerCase().includes(searchTerm.toLowerCase())
      )
    );
  }, [data, searchTerm]);

  // Sort data
  const sortedData = useMemo(() => {
    if (!sortConfig) return filteredData;

    return [...filteredData].sort((a, b) => {
      const aValue = a[sortConfig.key];
      const bValue = b[sortConfig.key];

      if (aValue === bValue) return 0;

      // Handle null/undefined values
      if (aValue == null && bValue == null) return 0;
      if (aValue == null) return 1;
      if (bValue == null) return -1;

      // Convert to string for comparison if not numbers
      const aComp = typeof aValue === 'number' ? aValue : String(aValue);
      const bComp = typeof bValue === 'number' ? bValue : String(bValue);

      const comparison = aComp < bComp ? -1 : 1;
      return sortConfig.direction === 'desc' ? comparison * -1 : comparison;
    });
  }, [filteredData, sortConfig]);

  // Paginate data
  const paginatedData = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize;
    return sortedData.slice(startIndex, startIndex + pageSize);
  }, [sortedData, currentPage, pageSize]);

  const totalPages = Math.ceil(sortedData.length / pageSize);

  const handleSort = (key: string) => {
    if (!sortable) return;

    const column = columns.find(col => col.key === key);
    if (!column?.sortable) return;

    setSortConfig(current => {
      if (current?.key === key) {
        return current.direction === 'asc' ? { key, direction: 'desc' } : null;
      }
      return { key, direction: 'asc' };
    });
  };

  const formatValue = (value: unknown, column: Column) => {
    if (value === null || value === undefined) return '-';

    if (column.format) {
      return column.format(value);
    }

    switch (column.type) {
      case 'currency':
        return new Intl.NumberFormat('en-US', {
          style: 'currency',
          currency: column.currency || 'USD',
          minimumFractionDigits: column.precision || 2,
          maximumFractionDigits: column.precision || 2,
        }).format(Number(value));

      case 'percentage':
        return `${Number(value).toFixed(column.precision || 1)}%`;

      case 'number':
        return Number(value).toLocaleString('en-US', {
          minimumFractionDigits: column.precision || 0,
          maximumFractionDigits: column.precision || 2,
        });

      case 'date':
        return new Date(value as string | number | Date).toLocaleDateString();

      default:
        return String(value);
    }
  };

  const exportToCSV = () => {
    const headers = columns.map(col => col.label).join(',');
    const rows = sortedData
      .map(row =>
        columns
          .map(col => {
            const value = formatValue(row[col.key], col);
            return `"${value.replace(/"/g, '""')}"`;
          })
          .join(',')
      )
      .join('\n');

    const csv = `${headers}\n${rows}`;
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${title || 'data'}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const getSortIcon = (columnKey: string) => {
    if (!sortConfig || sortConfig.key !== columnKey) {
      return <span className="text-gray-400">↕</span>;
    }
    return sortConfig.direction === 'asc' ? (
      <span className="text-blue-600">↑</span>
    ) : (
      <span className="text-blue-600">↓</span>
    );
  };

  return (
    <div
      className={`my-6 overflow-hidden rounded-lg border border-gray-200 bg-white ${className}`}
    >
      {/* Header */}
      {(title || searchable || exportable) && (
        <div className="border-b border-gray-200 bg-gray-50 px-6 py-4">
          <div className="flex items-center justify-between">
            <div>
              {title && (
                <h3 className="text-lg font-semibold text-gray-900">{title}</h3>
              )}
              <p className="mt-1 text-sm text-gray-600">
                {sortedData.length}{' '}
                {sortedData.length === 1 ? 'entry' : 'entries'}
                {searchTerm && ` (filtered from ${data.length})`}
              </p>
            </div>

            <div className="flex items-center space-x-4">
              {searchable && (
                <div className="relative">
                  <input
                    type="text"
                    placeholder="Search..."
                    value={searchTerm}
                    onChange={e => {
                      setSearchTerm(e.target.value);
                      setCurrentPage(1);
                    }}
                    className="rounded-md border border-gray-300 py-2 pl-8 pr-4 text-sm focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                  />
                  <span className="absolute left-2 top-2.5 text-sm text-gray-400">
                    🔍
                  </span>
                </div>
              )}

              {exportable && (
                <button
                  onClick={exportToCSV}
                  className="rounded-md bg-blue-600 px-4 py-2 text-sm text-white transition-colors hover:bg-blue-700"
                >
                  Export CSV
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead className="bg-gray-50">
            <tr>
              {showRowNumbers && (
                <th
                  className={`px-4 py-3 text-left text-xs font-medium uppercase tracking-wider text-gray-500 ${compact ? 'py-2' : ''}`}
                >
                  #
                </th>
              )}
              {columns.map(column => (
                <th
                  key={String(column.key)}
                  className={`cursor-pointer px-4 py-3 text-xs font-medium uppercase tracking-wider text-gray-500 transition-colors hover:bg-gray-100 ${
                    column.align === 'center'
                      ? 'text-center'
                      : column.align === 'right'
                        ? 'text-right'
                        : 'text-left'
                  } ${compact ? 'py-2' : ''}`}
                  style={{ width: column.width }}
                  onClick={() => handleSort(String(column.key))}
                >
                  <div className="flex items-center space-x-1">
                    <span>{column.label}</span>
                    {sortable &&
                      column.sortable !== false &&
                      getSortIcon(column.key)}
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200 bg-white">
            {paginatedData.map((row, index) => (
              <tr
                key={`row-${columns[0]?.key ? row[columns[0].key] : index}-${index}`}
                className={`${striped && index % 2 === 1 ? 'bg-gray-50' : ''} transition-colors hover:bg-gray-100`}
              >
                {showRowNumbers && (
                  <td
                    className={`whitespace-nowrap px-4 py-4 text-sm text-gray-500 ${compact ? 'py-2' : ''}`}
                  >
                    {(currentPage - 1) * pageSize + index + 1}
                  </td>
                )}
                {columns.map(column => (
                  <td
                    key={String(column.key)}
                    className={`whitespace-nowrap px-4 py-4 text-sm text-gray-900 ${
                      column.align === 'center'
                        ? 'text-center'
                        : column.align === 'right'
                          ? 'text-right'
                          : 'text-left'
                    } ${compact ? 'py-2' : ''}`}
                  >
                    {formatValue(row[column.key], column)}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="border-t border-gray-200 bg-gray-50 px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="text-sm text-gray-600">
              Showing {(currentPage - 1) * pageSize + 1} to{' '}
              {Math.min(currentPage * pageSize, sortedData.length)} of{' '}
              {sortedData.length} entries
            </div>

            <div className="flex items-center space-x-2">
              <button
                onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
                disabled={currentPage === 1}
                className="rounded-md border border-gray-300 px-3 py-1 text-sm transition-colors hover:bg-gray-100 disabled:cursor-not-allowed disabled:opacity-50"
              >
                Previous
              </button>

              <div className="flex items-center space-x-1">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                  const page = i + 1;
                  return (
                    <button
                      key={page}
                      onClick={() => setCurrentPage(page)}
                      className={`rounded-md px-3 py-1 text-sm transition-colors ${
                        currentPage === page
                          ? 'bg-blue-600 text-white'
                          : 'border border-gray-300 hover:bg-gray-100'
                      }`}
                    >
                      {page}
                    </button>
                  );
                })}
              </div>

              <button
                onClick={() =>
                  setCurrentPage(Math.min(totalPages, currentPage + 1))
                }
                disabled={currentPage === totalPages}
                className="rounded-md border border-gray-300 px-3 py-1 text-sm transition-colors hover:bg-gray-100 disabled:cursor-not-allowed disabled:opacity-50"
              >
                Next
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

