  create(
    data: Omit<ContentEntity, 'id' | 'createdAt' | 'updatedAt'>
  ): Promise<ContentEntity>;
  update(id: string, data: Partial<ContentEntity>): Promise<ContentEntity>;
  updateTranslation(
    id: string,
    locale: string,
