                      __html: content
                        .replace(
                          /^# (.*$)/gm,
                          '<h1 class="text-2xl font-bold mb-4">$1</h1>'
                        )
                        .replace(
                          /^## (.*$)/gm,
                          '<h2 class="text-xl font-semibold mb-3">$1</h2>'
