  blog: [
    {
      id: 'title-length',
      field: 'title',
      rule: 'length',
      message: 'Title should be between 10-60 characters',
      severity: 'error',
      required: true,
    },
    {
      id: 'title-seo',
      field: 'seoTitle',
      rule: 'length',
      message: 'SEO title should be between 30-60 characters',
      severity: 'warning',
      required: false,
    },
    {
      id: 'description-length',
      field: 'description',
      rule: 'length',
      message: 'Description should be between 120-160 characters',
      severity: 'warning',
      required: false,
    },
    {
      id: 'content-length',
      field: 'content',
      rule: 'minLength',
      message: 'Content should be at least 300 words',
      severity: 'error',
      required: true,
    },
