function Pagination({
  currentPage,
  totalPages,
  onPageChange,
}: {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
}) {
  const getVisiblePages = () => {
    const delta = 2;
    const range = [];
    const rangeWithDots = [];

    for (
      let i = Math.max(2, currentPage - delta);
      i <= Math.min(totalPages - 1, currentPage + delta);
      i++
    ) {
      range.push(i);
    }

    if (currentPage - delta > 2) {
      rangeWithDots.push(1, '...');
    } else {
      rangeWithDots.push(1);
    }

    rangeWithDots.push(...range);

    if (currentPage + delta < totalPages - 1) {
      rangeWithDots.push('...', totalPages);
    } else if (totalPages > 1) {
      rangeWithDots.push(totalPages);
    }

    return rangeWithDots;
  };

  if (totalPages <= 1) return null;

  const visiblePages = getVisiblePages();

  return (
    <div className="flex items-center justify-center gap-2 py-4">
      <Button
        variant="outline"
        size="sm"
        onClick={() => onPageChange(currentPage - 1)}
        disabled={currentPage <= 1}
        className="transition-all duration-200 hover:border-blue-300 hover:bg-blue-50 hover:text-blue-700"
      >
        Previous
      </Button>

      {visiblePages.map((page, index) => (
        <div key={`page-${page}-${index}`}>
          {page === '...' ? (
            <span className="px-3 py-2 text-gray-500">...</span>
          ) : (
            <Button
              variant={currentPage === page ? 'default' : 'outline'}
              size="sm"
              onClick={() => onPageChange(page as number)}
              className={cn(
                'transition-all duration-200',
                currentPage === page
                  ? 'bg-blue-600 hover:bg-blue-700'
                  : 'hover:border-blue-300 hover:bg-blue-50 hover:text-blue-700'
              )}
            >
              {page}
            </Button>
          )}
        </div>
      ))}

      <Button
        variant="outline"
        size="sm"
        onClick={() => onPageChange(currentPage + 1)}
        disabled={currentPage >= totalPages}
        className="transition-all duration-200 hover:border-blue-300 hover:bg-blue-50 hover:text-blue-700"
      >
        Next
      </Button>
    </div>
  );
}

export function SearchResults({
  results,
  loading = false,
  error = null,
  totalCount = 0,
  currentPage = 1,
  totalPages = 1,
  onPageChange,
  className,
  showPagination = true,
  emptyStateMessage = 'No results found',
  emptyStateDescription = 'Try adjusting your search terms or filters',
  layout = 'list',
  showMetrics = true,
}: SearchResultsProps) {
  if (error) {
    return (
      <div className={cn('py-12 text-center', className)}>
        <div className="mb-2 font-medium text-red-600">
          Error loading results
        </div>
        <div className="text-sm text-gray-500">{error}</div>
      </div>
    );
  }

  if (loading) {
    return (
      <div
        className={cn(
          layout === 'grid'
            ? 'grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3'
            : 'space-y-6',
          className
        )}
      >
        {Array.from({ length: layout === 'grid' ? 6 : 5 }).map((_, index) => (
          <SearchResultSkeleton
            key={`skeleton-${layout}-${index}`}
            layout={layout}
          />
        ))}
      </div>
    );
  }

  if (results.length === 0) {
    return (
      <div className={cn('py-16 text-center', className)}>
        <div className="mb-3 text-xl font-semibold text-gray-900">
          {emptyStateMessage}
        </div>
        <div className="mx-auto max-w-md text-base text-gray-500">
          {emptyStateDescription}
        </div>
      </div>
    );
  }

  return (
    <div className={cn('space-y-8', className)}>
      {/* Results Header */}
      <div className="flex items-center justify-between border-b border-gray-200 pb-4">
        <div className="text-sm text-gray-600">
          {totalCount > 0 && (
            <span className="font-medium">
              Showing {(currentPage - 1) * 10 + 1}-
              {Math.min(currentPage * 10, totalCount)} of{' '}
              {totalCount.toLocaleString()} results
            </span>
          )}
        </div>
      </div>

      {/* Results List/Grid */}
      <div
        className={cn(
          'duration-500 animate-in fade-in-0 slide-in-from-bottom-4',
          layout === 'grid'
            ? 'grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3'
            : 'space-y-6'
        )}
      >
        {results.map((result, index) => (
          <SearchResultCard
            key={result.id}
            result={result}
            layout={layout}
            showMetrics={showMetrics}
            index={index}
          />
        ))}
      </div>

      {/* Pagination */}
      {showPagination && onPageChange && totalPages > 1 && (
        <div className="border-t border-gray-200 pt-6">
          <Pagination
            currentPage={currentPage}
            totalPages={totalPages}
            onPageChange={onPageChange}
          />
        </div>
      )}
    </div>
  );
}

