}

export function SearchSuggestions({
  suggestions,
  recentSearches = [],
  popularSearches = [],
  trendingTopics = [],
  categories = [],
  tags = [],
  onSuggestionClick,
  onSearchClick,
  loading = false,
  className,
  maxItems = 5,
  showCategories = true,
  showTags = true,
  showRecent = true,
  showPopular = true,
  showTrending = true,
  variant = 'default',
}: SearchSuggestionsProps) {
  // Convert arrays to suggestion objects
  const recentSuggestions: SearchSuggestion[] = recentSearches.map(
    (search, index) => ({
      id: `recent-${index}`,
      text: search,
      type: 'recent',
    })
  );

  const popularSuggestions: SearchSuggestion[] = popularSearches.map(
    (search, index) => ({
      id: `popular-${index}`,
      text: search,
      type: 'popular',
    })
  );

  const trendingSuggestions: SearchSuggestion[] = trendingTopics.map(
    (topic, index) => ({
      id: `trending-${index}`,
      text: topic,
      type: 'trending',
    })
  );

  const categorySuggestions: SearchSuggestion[] = categories.map(
    (category, index) => ({
      id: `category-${index}`,
      text: category.name,
      type: 'category',
      count: category.count,
      url: category.url,
      description: `${category.count} items`,
    })
  );

  const tagSuggestions: SearchSuggestion[] = tags.map((tag, index) => ({
    id: `tag-${index}`,
    text: tag.name,
    type: 'tag',
    count: tag.count,
    url: tag.url,
    description: `${tag.count} items`,
  }));

  const handleSuggestionClick = (suggestion: SearchSuggestion) => {
    if (onSuggestionClick) {
      onSuggestionClick(suggestion);
    }
    if (onSearchClick && !suggestion.url) {
      onSearchClick(suggestion.text);
    }
  };

  if (loading) {
    return (
      <div className={cn('space-y-4', className)}>
        <Card className="animate-pulse">
          <CardHeader>
            <Skeleton className="h-5 w-32" />
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {Array.from({ length: 3 }).map((_, index) => (
                <SuggestionSkeleton key={index} variant={variant} />
              ))}
            </div>
          </CardContent>
        </Card>
        <Card className="animate-pulse">
          <CardHeader>
            <Skeleton className="h-5 w-40" />
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {Array.from({ length: 2 }).map((_, index) => (
                <SuggestionSkeleton key={index} variant={variant} />
              ))}
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  let sectionIndex = 0;

  return (
    <div
      className={cn('space-y-4 duration-500 animate-in fade-in-0', className)}
    >
      {/* Custom Suggestions */}
      {suggestions.length > 0 && (
        <SuggestionSection
          title="Suggestions"
          icon={<Sparkles className="h-4 w-4 text-blue-500" />}
          items={suggestions}
          onItemClick={handleSuggestionClick}
          maxItems={maxItems}
          variant={variant}
          sectionIndex={sectionIndex++}
        />
      )}

      {/* Recent Searches */}
      {showRecent && recentSuggestions.length > 0 && (
        <SuggestionSection
          title="Recent Searches"
          icon={<Clock className="h-4 w-4 text-gray-500" />}
          items={recentSuggestions}
          onItemClick={handleSuggestionClick}
          maxItems={maxItems}
          variant={variant}
          sectionIndex={sectionIndex++}
        />
      )}

      {/* Popular Searches */}
      {showPopular && popularSuggestions.length > 0 && (
        <SuggestionSection
          title="Popular Searches"
          icon={<Flame className="h-4 w-4 text-orange-500" />}
          items={popularSuggestions}
          onItemClick={handleSuggestionClick}
          maxItems={maxItems}
          variant={variant}
          sectionIndex={sectionIndex++}
        />
      )}

      {/* Trending Topics */}
      {showTrending && trendingSuggestions.length > 0 && (
        <SuggestionSection
          title="Trending Topics"
          icon={<TrendingUp className="h-4 w-4 text-red-500" />}
          items={trendingSuggestions}
          onItemClick={handleSuggestionClick}
          maxItems={maxItems}
          variant={variant}
          sectionIndex={sectionIndex++}
        />
      )}

      {/* Categories */}
      {showCategories && categorySuggestions.length > 0 && (
        <SuggestionSection
          title="Browse by Category"
          icon={<Hash className="h-4 w-4 text-green-500" />}
          items={categorySuggestions}
          onItemClick={handleSuggestionClick}
          maxItems={maxItems}
          variant={variant}
          sectionIndex={sectionIndex++}
        />
      )}

      {/* Tags */}
      {showTags && tagSuggestions.length > 0 && (
        <SuggestionSection
          title="Popular Tags"
          icon={<Hash className="h-4 w-4 text-purple-500" />}
          items={tagSuggestions}
          onItemClick={handleSuggestionClick}
          maxItems={maxItems}
          variant={variant}
          sectionIndex={sectionIndex++}
        />
      )}

      {/* Empty State */}
      {suggestions.length === 0 &&
        recentSuggestions.length === 0 &&
        popularSuggestions.length === 0 &&
        trendingSuggestions.length === 0 &&
        categorySuggestions.length === 0 &&
        tagSuggestions.length === 0 && (
          <Card className="duration-500 animate-in fade-in-0 slide-in-from-bottom-4">
            <CardContent className="pt-6">
              <div className="py-12 text-center">
                <div className="relative">
                  <Search className="mx-auto mb-4 h-12 w-12 text-gray-300 transition-all duration-300 hover:scale-110 hover:text-gray-400" />
                  <div className="absolute -right-1 -top-1">
                    <Sparkles className="h-4 w-4 animate-pulse text-blue-400" />
                  </div>
                </div>
                <div className="mb-2 text-base font-medium text-gray-600">
                  Start typing to see search suggestions
                </div>
                <div className="mx-auto max-w-sm text-sm text-gray-500">
                  Discover coffee products, market insights, and origin stories
                </div>
              </div>
            </CardContent>
          </Card>
        )}
    </div>
  );
}

