'use client';

import { createScopedLogger } from '@/shared/utils/logger';

const logger = createScopedLogger('AnalyticsProvider');

import { usePathname, useSearchParams } from 'next/navigation';
import Script from 'next/script';
import React, {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
} from 'react';

import { CoreWebVitalsMonitor } from '../performance/CoreWebVitalsMonitor';

// Extend Window interface for Google Analytics
declare global {
  interface Window {
    gtag: (
      command: 'config' | 'event' | 'js' | 'set',
      targetId: string | Date,
      config?: Record<string, string | number | boolean>
    ) => void;
    dataLayer: any[];
  }
}

// Analytics configuration
interface AnalyticsConfig {
  googleAnalyticsId?: string;
  enableGoogleAnalytics: boolean;
  enableWebVitals: boolean;
  enableEcommerce: boolean;
  enableCustomEvents: boolean;
  enableConsoleLogging: boolean;
  enableVisualIndicator: boolean;
  cookieConsent: boolean;
  debugMode: boolean;
}

// E-commerce event data
interface EcommerceEventData {
  transaction_id?: string;
  value?: number;
  currency?: string;
  items?: Array<{
    item_id: string;
    item_name: string;
    category: string;
    quantity: number;
    price: number;
    item_brand?: string;
    item_category2?: string;
    item_category3?: string;
    item_variant?: string;
  }>;
  coupon?: string;
  shipping?: number;
  tax?: number;
}

// Custom event data
interface CustomEventData {
  event_category?: string;
  event_label?: string;
  value?: number;
  custom_parameters?: Record<string, any>;
}

// User properties
interface UserProperties {
  user_id?: string;
  customer_type?: 'B2B' | 'B2C';
  subscription_status?: string;
  preferred_language?: string;
  country?: string;
  industry?: string;
  company_size?: string;
}

// Analytics context
interface AnalyticsContextType {
  config: AnalyticsConfig;
  isLoaded: boolean;
  trackPageView: (url: string, title?: string) => void;
  trackEvent: (eventName: string, eventData?: CustomEventData) => void;
  trackEcommerce: (eventName: string, eventData: EcommerceEventData) => void;
  setUserProperties: (properties: UserProperties) => void;
  setConsent: (consent: boolean) => void;
  enableAnalytics: () => void;
  disableAnalytics: () => void;
}

const AnalyticsContext = createContext<AnalyticsContextType | null>(null);

// Default configuration
const defaultConfig: AnalyticsConfig = {
  ...(process.env.NEXT_PUBLIC_GA4_MEASUREMENT_ID && {
    googleAnalyticsId: process.env.NEXT_PUBLIC_GA4_MEASUREMENT_ID,
  }),
  enableGoogleAnalytics: true,
  enableWebVitals: true,
  enableEcommerce: true,
  enableCustomEvents: true,
  enableConsoleLogging: process.env.NODE_ENV === 'development',
  enableVisualIndicator: process.env.NODE_ENV === 'development',
  cookieConsent: false,
  debugMode: process.env.NODE_ENV === 'development',
};

interface AnalyticsProviderProps {
  children: React.ReactNode;
  config?: Partial<AnalyticsConfig>;
}

/**
 * Analytics Provider Component
 *
 * Provides comprehensive analytics functionality including:
 * - Google Analytics 4 integration
 * - Core Web Vitals monitoring
 * - E-commerce tracking
 * - Custom event tracking
 * - User properties and consent management
 * - GDPR compliance features
 */
export function AnalyticsProvider({
  children,
  config: userConfig = {},
}: AnalyticsProviderProps) {
  const config = { ...defaultConfig, ...userConfig };
  const [isLoaded, setIsLoaded] = useState(false);
  const [consentGiven, setConsentGiven] = useState(config.cookieConsent);
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const initializedRef = useRef(false);

  // Initialize Google Analytics
  const initializeGA = () => {
    if (!config.googleAnalyticsId || !consentGiven) return;

    window.dataLayer = window.dataLayer || [];
    window.gtag = function gtag(...args: any[]) {
      window.dataLayer.push(args);
    };

    window.gtag('js', new Date());
    window.gtag('config', config.googleAnalyticsId, {
      page_title: document.title,
      page_location: window.location.href,
      debug_mode: config.debugMode,
      send_page_view: false, // We'll handle page views manually
    });

    // Configure enhanced e-commerce
    if (config.enableEcommerce) {
      window.gtag('config', config.googleAnalyticsId, {
        custom_map: {
          custom_parameter_1: 'customer_type',
          custom_parameter_2: 'industry',
          custom_parameter_3: 'company_size',
        },
      } as any);
    }

    setIsLoaded(true);
    initializedRef.current = true;

    // Analytics logging removed for production
  };

  // Track page view
  const trackPageView = (url: string, title?: string) => {
    if (!isLoaded || !consentGiven) return;

    window.gtag('config', config.googleAnalyticsId!, {
      page_title: title || document.title,
      page_location: url,
    });

    // Analytics logging removed for production
  };

  // Track custom event
  const trackEvent = (eventName: string, eventData: CustomEventData = {}) => {
    if (!isLoaded || !consentGiven) return;

    const {
      event_category,
      event_label,
      value,
      custom_parameters = {},
    } = eventData;

    const eventParams: any = {
      ...custom_parameters,
    };

    if (event_category !== undefined)
      eventParams.event_category = event_category;
    if (event_label !== undefined) eventParams.event_label = event_label;
    if (value !== undefined) eventParams.value = value;

    window.gtag('event', eventName, eventParams);

    // Analytics logging removed for production
  };

  // Track e-commerce event
  const trackEcommerce = (eventName: string, eventData: EcommerceEventData) => {
    if (!isLoaded || !consentGiven || !config.enableEcommerce) return;

    window.gtag('event', eventName, eventData as any);

    // Analytics logging removed for production
  };

  // Set user properties
  const setUserProperties = (properties: UserProperties) => {
    if (!isLoaded || !consentGiven) return;

    window.gtag('config', config.googleAnalyticsId!, {
      user_properties: properties,
    } as any);

    // Analytics logging removed for production
  };

  // Set consent
  const setConsent = (consent: boolean) => {
    setConsentGiven(consent);

    if (consent && !initializedRef.current) {
      initializeGA();
    }

    if (window.gtag) {
      (window.gtag as any)('consent', 'update', {
        analytics_storage: consent ? 'granted' : 'denied',
        ad_storage: consent ? 'granted' : 'denied',
      });
    }

    // Analytics logging removed for production
  };

  // Enable analytics
  const enableAnalytics = () => {
    setConsent(true);
  };

  // Disable analytics
  const disableAnalytics = () => {
    setConsent(false);
  };

  // Track page changes
  useEffect(() => {
    if (!isLoaded || !consentGiven) return;

    const url =
      pathname + (searchParams.toString() ? `?${searchParams.toString()}` : '');
    trackPageView(url);
  }, [pathname, searchParams, isLoaded, consentGiven]);

  // Initialize on mount
  useEffect(() => {
    if (consentGiven && !initializedRef.current) {
      initializeGA();
    }
  }, [consentGiven]);

  // Track user engagement
  useEffect(() => {
    if (!isLoaded || !consentGiven) return;

    let engagementTimer: NodeJS.Timeout;
    let scrollDepth = 0;
    let maxScrollDepth = 0;

    // Track scroll depth
    const handleScroll = () => {
      const scrollTop =
        window.pageYOffset || document.documentElement.scrollTop;
      const documentHeight =
        document.documentElement.scrollHeight - window.innerHeight;
      scrollDepth = Math.round((scrollTop / documentHeight) * 100);

      if (scrollDepth > maxScrollDepth) {
        maxScrollDepth = scrollDepth;

        // Track scroll milestones
        if (maxScrollDepth >= 25 && maxScrollDepth < 50) {
          trackEvent('scroll_depth', {
            event_category: 'engagement',
            value: 25,
          });
        } else if (maxScrollDepth >= 50 && maxScrollDepth < 75) {
          trackEvent('scroll_depth', {
            event_category: 'engagement',
            value: 50,
          });
        } else if (maxScrollDepth >= 75 && maxScrollDepth < 90) {
          trackEvent('scroll_depth', {
            event_category: 'engagement',
            value: 75,
          });
        } else if (maxScrollDepth >= 90) {
          trackEvent('scroll_depth', {
            event_category: 'engagement',
            value: 90,
          });
        }
      }
    };

    // Track time on page
    const startTime = Date.now();
    engagementTimer = setInterval(() => {
      const timeOnPage = Math.round((Date.now() - startTime) / 1000);

      // Track engagement milestones
      if (timeOnPage === 30) {
        trackEvent('time_on_page', { event_category: 'engagement', value: 30 });
      } else if (timeOnPage === 60) {
        trackEvent('time_on_page', { event_category: 'engagement', value: 60 });
      } else if (timeOnPage === 180) {
        trackEvent('time_on_page', {
          event_category: 'engagement',
          value: 180,
        });
      }
    }, 1000);

    window.addEventListener('scroll', handleScroll, { passive: true });

    return () => {
      clearInterval(engagementTimer);
      window.removeEventListener('scroll', handleScroll);
    };
  }, [isLoaded, consentGiven]);

  const contextValue: AnalyticsContextType = {
    config,
    isLoaded,
    trackPageView,
    trackEvent,
    trackEcommerce,
    setUserProperties,
    setConsent,
    enableAnalytics,
    disableAnalytics,
  };

  return (
    <AnalyticsContext.Provider value={contextValue}>
      {/* Google Analytics Script */}
      {config.enableGoogleAnalytics &&
        config.googleAnalyticsId &&
        consentGiven && (
          <Script
            src={`https://www.googletagmanager.com/gtag/js?id=${config.googleAnalyticsId}`}
            strategy="afterInteractive"
            onLoad={() => {
              if (!initializedRef.current) {
                initializeGA();
              }
            }}
          />
        )}

      {/* Core Web Vitals Monitor */}
      {config.enableWebVitals && (
        <CoreWebVitalsMonitor
          enableAnalytics={isLoaded && consentGiven}
          enableConsoleLogging={config.enableConsoleLogging}
          enableVisualIndicator={config.enableVisualIndicator}
          onMetricCapture={metric => {
            if (config.enableCustomEvents) {
              trackEvent('web_vitals', {
                event_category: 'performance',
                event_label: metric.name,
                value: Math.round(
                  metric.name === 'CLS' ? metric.value * 1000 : metric.value
                ),
                custom_parameters: {
                  metric_rating: metric.rating,
                  metric_delta: metric.delta,
                  navigation_type: metric.navigationType,
                },
              });
            }
          }}
        />
      )}

      {children}
    </AnalyticsContext.Provider>
  );
}

// Hook to use analytics
export function useAnalytics() {
  const context = useContext(AnalyticsContext);
  if (!context) {
    throw new Error('useAnalytics must be used within an AnalyticsProvider');
  }
  return context;
}

// Higher-order component for tracking page views
export function withAnalytics<P extends object>(
  Component: React.ComponentType<P>,
  eventName?: string
) {
  return function AnalyticsWrappedComponent(props: P) {
    const { trackEvent } = useAnalytics();

    useEffect(() => {
      if (eventName) {
        trackEvent(eventName, {
          event_category: 'page_interaction',
          event_label: Component.displayName || Component.name,
        });
      }
    }, []);

    return <Component {...props} />;
  };
}

export default AnalyticsProvider;

'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import { onCLS, onFCP, onINP, onLCP, onTTFB, type Metric } from 'web-vitals';

import { createScopedLogger } from '@/shared/utils/logger';

const logger = createScopedLogger('CoreWebVitalsMonitor');

// Core Web Vitals thresholds (Google's recommended values)
const THRESHOLDS = {
  LCP: { good: 2500, needsImprovement: 4000 }, // Largest Contentful Paint
  INP: { good: 200, needsImprovement: 500 }, // Interaction to Next Paint
  CLS: { good: 0.1, needsImprovement: 0.25 }, // Cumulative Layout Shift
  FCP: { good: 1800, needsImprovement: 3000 }, // First Contentful Paint
  TTFB: { good: 800, needsImprovement: 1800 }, // Time to First Byte
};

// Performance rating based on thresholds
type PerformanceRating = 'good' | 'needs-improvement' | 'poor';

interface WebVitalMetric {
  name: string;
  value: number;
  rating: PerformanceRating;
  delta: number;
  id: string;
  navigationType: string;
}

interface CoreWebVitalsData {
  LCP?: WebVitalMetric;
  INP?: WebVitalMetric;
  CLS?: WebVitalMetric;
  FCP?: WebVitalMetric;
  TTFB?: WebVitalMetric;
}

interface CoreWebVitalsMonitorProps {
  enableAnalytics?: boolean;
  enableConsoleLogging?: boolean;
  enableVisualIndicator?: boolean;
  onMetricCapture?: (metric: WebVitalMetric) => void;
  analyticsEndpoint?: string;
}

/**
 * Core Web Vitals Monitor Component
 *
 * Monitors and reports Core Web Vitals metrics including:
 * - LCP (Largest Contentful Paint)
 * - INP (Interaction to Next Paint)
 * - CLS (Cumulative Layout Shift)
 * - FCP (First Contentful Paint)
 * - TTFB (Time to First Byte)
 */
export function CoreWebVitalsMonitor({
  enableAnalytics = true,
  enableConsoleLogging = false,
  enableVisualIndicator = false,
  onMetricCapture,
  analyticsEndpoint = '/api/analytics/web-vitals',
}: CoreWebVitalsMonitorProps) {
  const [metrics, setMetrics] = useState<CoreWebVitalsData>({});
  const [isVisible, setIsVisible] = useState(enableVisualIndicator);
  const sentMetrics = useRef(new Set<string>());

  // Get performance rating based on metric value and thresholds
  const getPerformanceRating = (
    name: string,
    value: number
  ): PerformanceRating => {
    const threshold = THRESHOLDS[name as keyof typeof THRESHOLDS];
    if (!threshold) return 'good';

    if (value <= threshold.good) return 'good';
    if (value <= threshold.needsImprovement) return 'needs-improvement';
    return 'poor';
  };

  // Send metric to analytics
  const sendToAnalytics = useCallback(
    async (metric: WebVitalMetric) => {
      if (!enableAnalytics) return;

      try {
        // Send to Google Analytics 4 if available
        if (typeof window !== 'undefined' && window.gtag) {
          window.gtag('event', metric.name, {
            event_category: 'Web Vitals',
            event_label: metric.id,
            value: Math.round(
              metric.name === 'CLS' ? metric.value * 1000 : metric.value
            ),
            metric_rating: metric.rating,
            metric_delta: metric.delta,
            navigation_type: metric.navigationType,
          });
        }

        // Send to custom analytics endpoint
        if (analyticsEndpoint) {
          await fetch(analyticsEndpoint, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({
              metric,
              timestamp: Date.now(),
              url: window.location.href,
              userAgent: navigator.userAgent,
              connection: (
                navigator as { connection?: { effectiveType: string } }
              ).connection?.effectiveType,
            }),
          });
        }
      } catch (error) {
        // Error logging removed for production
      }
    },
    [enableAnalytics, analyticsEndpoint, enableConsoleLogging]
  );

  // Handle metric capture
  const handleMetric = useCallback(
    (metric: Metric) => {
      const webVitalMetric: WebVitalMetric = {
        name: metric.name,
        value: metric.value,
        rating: getPerformanceRating(metric.name, metric.value),
        delta: metric.delta,
        id: metric.id,
        navigationType: metric.navigationType || 'navigate',
      };

      // Update state
      setMetrics(prev => ({
        ...prev,
        [metric.name]: webVitalMetric,
      }));

      // Log to console if enabled and in development
      // Development logging removed for production

      // Send to analytics (only once per metric per page load)
      const metricKey = `${metric.name}-${metric.id}`;
      if (!sentMetrics.current.has(metricKey)) {
        sentMetrics.current.add(metricKey);
        sendToAnalytics(webVitalMetric);
      }

      // Call custom handler
      if (onMetricCapture) {
        onMetricCapture(webVitalMetric);
      }
    },
    [enableConsoleLogging, onMetricCapture, sendToAnalytics]
  );

  // Initialize Web Vitals monitoring
  useEffect(() => {
    if (typeof window === 'undefined') return;

    // Monitor Core Web Vitals
    onCLS(handleMetric);
    onFCP(handleMetric);
    onINP(handleMetric);
    onLCP(handleMetric);
    onTTFB(handleMetric);

    // Monitor additional performance metrics
    if ('PerformanceObserver' in window) {
      // Monitor Long Tasks (for performance debugging)
      try {
        const longTaskObserver = new PerformanceObserver(list => {
          for (const entry of list.getEntries()) {
            if (entry.duration > 50) {
              // Performance logging removed for production
            }
          }
        });
        longTaskObserver.observe({ entryTypes: ['longtask'] });
      } catch (error) {
        // Long Task API not supported
      }

      // Monitor Layout Shifts for debugging
      try {
        interface LayoutShiftEntry extends PerformanceEntry {
          value: number;
          sources: Array<{ node?: Element }>;
        }

        const layoutShiftObserver = new PerformanceObserver(list => {
          for (const entry of list.getEntries()) {
            const layoutShiftEntry = entry as LayoutShiftEntry;
            if (layoutShiftEntry.value > 0.1) {
              // Performance logging removed for production
            }
          }
        });
        layoutShiftObserver.observe({ entryTypes: ['layout-shift'] });
      } catch (error) {
        // Layout Shift API not supported
      }
    }

    // Auto-hide visual indicator after 10 seconds
    if (enableVisualIndicator) {
      const timer = setTimeout(() => setIsVisible(false), 10000);
      return () => clearTimeout(timer);
    }

    // Return undefined for consistency
    return undefined;
  }, [
    enableAnalytics,
    enableConsoleLogging,
    enableVisualIndicator,
    onMetricCapture,
    analyticsEndpoint,
    handleMetric,
  ]);

  // Visual indicator component
  if (!isVisible || !enableVisualIndicator) {
    return null;
  }

  const getMetricColor = (rating: PerformanceRating) => {
    switch (rating) {
      case 'good':
        return 'text-green-600 bg-green-50';
      case 'needs-improvement':
        return 'text-yellow-600 bg-yellow-50';
      case 'poor':
        return 'text-red-600 bg-red-50';
      default:
        return 'text-gray-600 bg-gray-50';
    }
  };

  const formatValue = (name: string, value: number) => {
    if (name === 'CLS') {
      return value.toFixed(3);
    }
    return `${Math.round(value)}ms`;
  };

  return (
    <div className="fixed bottom-2 right-2 z-50 hidden max-w-xs rounded-lg border border-gray-200 bg-white p-3 shadow-lg sm:bottom-4 sm:right-4 sm:block sm:max-w-sm sm:p-4">
      <div className="mb-2 flex items-center justify-between">
        <h3 className="text-sm font-semibold text-gray-900">Core Web Vitals</h3>
        <button
          onClick={() => setIsVisible(false)}
          className="text-sm text-gray-400 hover:text-gray-600"
          aria-label="Close Web Vitals monitor"
        >
          ×
        </button>
      </div>

      <div className="space-y-2">
        {Object.entries(metrics).map(([name, metric]) => (
          <div key={name} className="flex items-center justify-between">
            <span className="text-xs font-medium text-gray-700">{name}</span>
            <span
              className={`rounded px-2 py-1 text-xs ${getMetricColor(metric.rating)}`}
            >
              {formatValue(name, metric.value)}
            </span>
          </div>
        ))}
      </div>

      <div className="mt-3 text-xs text-gray-500">
        <div className="flex items-center space-x-2">
          <div className="flex items-center">
            <div className="mr-1 h-2 w-2 rounded-full bg-green-500"></div>
            <span>Good</span>
          </div>
          <div className="flex items-center">
            <div className="mr-1 h-2 w-2 rounded-full bg-yellow-500"></div>
            <span>Needs Improvement</span>
          </div>
          <div className="flex items-center">
            <div className="mr-1 h-2 w-2 rounded-full bg-red-500"></div>
            <span>Poor</span>
          </div>
        </div>
      </div>
    </div>
  );
}

// Hook for accessing Web Vitals data
export function useWebVitals() {
  const [metrics, setMetrics] = useState<CoreWebVitalsData>({});

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const handleMetric = (metric: Metric) => {
