  cloudinaryId,
  useCloudinary = false,
  trackPerformance = false,
  priority,
  // Extract Next.js Image props
  width,
  height,
  fill,
  sizes,
  quality,
  placeholder,
  style,
  loader,
  unoptimized,
  overrideSrc,
  onLoadingComplete,
  decoding,
  loading,
  lazyBoundary,
  lazyRoot,
}: OptimizedImageProps) {
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [loadStartTime, setLoadStartTime] = useState<number>(0);

  // Determine the image source and blur placeholder
  const imageSource =
    useCloudinary && cloudinaryId
      ? cloudinaryService.getOptimizedImageUrl(cloudinaryId, {
          priority: optimizeForLCP ? 'high' : 'auto',
          responsive: true,
        })
      : src;

  const imageBlurDataURL =
    useCloudinary && cloudinaryId && showBlurPlaceholder
      ? cloudinaryService.getBlurPlaceholder(cloudinaryId)
      : blurDataURL;

  // Handle successful image load
  const handleLoad = useCallback(() => {
    setIsLoading(false);

    if (trackPerformance && loadStartTime > 0) {
      const loadTime = performance.now() - loadStartTime;

      // Track performance metrics
      // Performance tracking removed for production
    }

    onLoadComplete?.();
  }, [
    onLoadComplete,
    trackPerformance,
    loadStartTime,
    optimizeForLCP,
    useCloudinary,
  ]);

  // Handle image load error
  const handleError = useCallback(() => {
    setIsLoading(false);
    setHasError(true);

    if (trackPerformance) {
      // Track error metrics
      // Error tracking removed for production
    }

    onLoadError?.();
  }, [onLoadError, trackPerformance, optimizeForLCP, useCloudinary]);

  // Track load start time and preload critical images
  useEffect(() => {
    if (trackPerformance) {
      setLoadStartTime(performance.now());
    }

    // Preload critical images for LCP optimization
    if (optimizeForLCP && !lazy && useCloudinary && cloudinaryId) {
      coreWebVitalsOptimizer.optimizeImagesForWebVitals([
        {
          publicId: cloudinaryId,
          priority: 'high',
          ...(sizes && { sizes }),
        },
      ]);
    }
  }, [
    trackPerformance,
    optimizeForLCP,
    lazy,
    useCloudinary,
    cloudinaryId,
    sizes,
  ]);

  // Show error state
  if (hasError) {
    if (errorComponent) {
      return <>{errorComponent}</>;
    }

    return (
      <div
        className={cn(
          'flex items-center justify-center bg-gray-100 text-gray-400',
          className
        )}
        {...(fill ? {} : { style: { width: width, height: height } })}
      >
        <svg
          className="h-8 w-8"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 002 2v12a2 2 0 002 2z"
          />
        </svg>
      </div>
    );
  }

  // Show loading state
  if (isLoading && loadingComponent) {
    return <>{loadingComponent}</>;
  }

  return (
    <div className="relative">
      <Image
        src={imageSource}
        alt={alt}
        {...(width !== undefined && { width })}
        {...(height !== undefined && { height })}
        {...(fill !== undefined && { fill })}
        {...(sizes && { sizes })}
        {...(quality !== undefined && { quality })}
        {...(style && { style })}
        {...(loader && { loader })}
        {...(unoptimized !== undefined && { unoptimized })}
        {...(overrideSrc && { overrideSrc })}
        {...(onLoadingComplete && { onLoadingComplete })}
        {...(decoding && { decoding })}
        {...(lazyBoundary && { lazyBoundary })}
        {...(lazyRoot && { lazyRoot })}
        className={cn(
          'transition-opacity duration-300',
          isLoading && showBlurPlaceholder ? 'opacity-0' : 'opacity-100',
          className
        )}
        onLoad={handleLoad}
        onError={handleError}
        priority={Boolean(optimizeForLCP || priority)}
        loading={
          loading || (lazy && !optimizeForLCP && !priority ? 'lazy' : 'eager')
        }
        placeholder={
          placeholder ||
          (showBlurPlaceholder && imageBlurDataURL ? 'blur' : 'empty')
        }
        {...(imageBlurDataURL && { blurDataURL: imageBlurDataURL })}
      />

      {/* Loading overlay with blur placeholder */}
      {isLoading && showBlurPlaceholder && (
        <div
          className={cn(
            'absolute inset-0 flex items-center justify-center bg-gray-100',
            className
          )}
        >
          <div className="h-8 w-8 animate-spin rounded-full border-2 border-gray-300 border-t-gray-600" />
        </div>
      )}
    </div>
  );
}

